'use strict';
// Stronghold Destroyer — the Master Guide, word for word, for the Help screen (its topic "The Master Guide" and its search).
// Made by tools/master_guide.js from the same pages as design/Stronghold-Destroyer-Master-Guide-v3.pdf (November 15, 2026). Do not edit by hand:
// change the guide's words in tools/master_guide.js and run it again. The pictures come from the game (u:, b:, r:, w:, i: names).
const GUIDE_DATA = {"made":"November 15, 2026","sections":[{"id":"read","title":"How to read this guide"},{"id":"s1","title":"1. The Goal and How a Game Starts"},{"id":"s2","title":"2. Stuck? Start Here"},{"id":"s3","title":"3. The Four Factions"},{"id":"s4","title":"4. The Five Castle Stages"},{"id":"s5","title":"5. Controls and Buttons"},{"id":"s6","title":"6. Units and Soldiers"},{"id":"s7","title":"7. Combat and Defenses"},{"id":"s8","title":"8. Buildings and Industries"},{"id":"s9","title":"9. Goods, Weapons and How Soldiers Are Made"},{"id":"s10","title":"10. Economy, Mood and Trade"},{"id":"s11","title":"11. Citizens and How You Read Them"},{"id":"s12","title":"12. Fire and Repair"},{"id":"s13","title":"13. The World, the Map and the Table"},{"id":"s14","title":"14. Rivals, Trade and Winning"},{"id":"s15","title":"15. Advisor, Hints, Help, Settings and Saving"},{"id":"s16","title":"16. Glossary and Search Words"},{"id":"s17","title":"17. Still Open"}],"articles":[{"id":"g-read-how-to-read-this-guide","cat":"guide","sec":"read","secTitle":"How to read this guide","title":"How to read this guide","pic":"i:book","blocks":[{"t":"ul","items":["<b>Set</b> means you decided it. It is the rule of the game.","<b>Build</b> means it is how Claude Code set a number or choice in the current game. You can change it. These numbers are meant to be tuned.","<span class=\"new\">NEW</span> marks everything that has come into the game since version 2. <span class=\"new fx\">CORRECTED</span> marks a place where version 2 said one thing and the game now does another.","<b>Pictures:</b> every screen, box and button in this guide is a photograph of the real game, taken by Claude Code from the game itself on November 15, 2026. Every person, soldier, siege engine, building, wall, tower, good and weapon is shown as the game draws it today. The soldiers, scenes, bricks and ground from your design sheet are shown as the design pictures.","<b>Stuck?</b> Go straight to section 2. It lists the common problems, what to do, and a few Art of War ideas for winning.","<b>Big text:</b> this edition uses larger letters than version 2, so it has more pages. Nothing was left out to make it shorter."]},{"t":"p","h":"This is the one guide to keep: it now holds the Troop Controls Guide from Phase 4E as well (the troop diamond, the formations and the phone, in section 5). <span class=\"new\">NEW</span>"},{"t":"p","h":"All of this guide is in the game’s Help too: tap the ? and choose <b>The Master Guide</b> from the Topics list, or type what you need in the search box, and the search looks through the whole guide as well as the Help answers. When a rule changes, this guide and the Help change together. <span class=\"new\">NEW</span>"}],"summary":"Set means you decided it. It is the rule of the game."},{"id":"g-read-what-is-new-in-version-3","cat":"guide","sec":"read","secTitle":"How to read this guide","title":"What is new in version 3","pic":"i:book","blocks":[{"t":"table","head":["What","In short","Section"],"rows":[["Longer peace <span class=\"new\">NEW</span>","10 minutes of peace before the first raid on Easy and Medium, 5 on Hard. Bandits wait too.","1, 2"],["Calling citizens <span class=\"new\">NEW</span>","The Citizen button in the Town list calls one more citizen, for food and gold. Unhappy people: slower and dearer. Wars won and generals: sooner and cheaper.","11"],["Which building is asking <span class=\"new\">NEW</span>","A coloured marker with an exclamation point floats over each building that has something to say, and the same marker is in the alert, so you know which one to go to.","4, 15"],["Arrows when you place <span class=\"new\">NEW</span>","Drag a building where you want it and let go: four arrows appear around it and you tap the way it should face. The Turn button and its text are gone.","5, 8"],["Low Brick Wall, men on every wall <span class=\"new\">NEW</span>","A low brick wall you can buy (3 stone); palisades have a walkway; soldiers of any kind can stand on any wall but the low one and in the bigger towers, and idle archers climb up when raiders come.","7"],["Edit Walls <span class=\"new\">NEW</span>","A button in the Castle list drops every wall flat so you can see and draw them, while the game keeps going. Tap anywhere else and they stand up.","5, 7"],["Ill people, the apothecary <span class=\"new\">NEW</span>","You are told when more than ten are ill. The apothecary holds up to five carers (more carers, faster care); tap it or the school to see who is there.","8, 11"],["Voice volume <span class=\"new\">NEW</span>","Settings has a Voice volume slider beside Voice on or off.","15"],["Tap a field or farm <span class=\"new\">NEW</span>","A tap or click anywhere on a field or farm, even on someone working it, opens its box right beside it: its crops or animals, its people, its well, lookout and guards.","8"],["Food first <span class=\"new\">NEW</span>","When food runs low, people pick food by themselves: those with no job pick berries, no one picking food is called away, and if the stores run nearly empty people leave other work to pick food.","10"],["The Field <span class=\"new\">NEW</span>","5 fields, 10 people each. Tap a field to choose how many grow wheat (fastest), corn (next) and grapes (slowest). All three can grow at once, in strips.","8, 10"],["The Farm <span class=\"new\">NEW</span>","2 farms, 5 people each. Tick the animals it raises (chickens, cows, pigs, ducks; turkeys and sheep for the feast) and watch them walk about the pen. It gets better with time, and with a stable.","8"],["Guards, wells and lookouts <span class=\"new\">NEW</span>","Guards with a knight’s strength come with a field (2) and a farm (1), free, as a tower comes with its knight. A well grows things 25% faster; a lookout tower sees around and rings the bell for raiders.","8"],["Happy people grow more <span class=\"new\">NEW</span>","Very happy people grow food 25% faster in the fields and farms; upset people 20% slower.","8, 10"],["Animals sell at the top price <span class=\"new\">NEW</span>","At the market, farm animals always sell for the top price, whatever the mood or the school, far more than crops.","10"],["Smoother walking <span class=\"new\">NEW</span>","People no longer shake or turn back and forth near trees, bushes or each other. They go round anyone in the way, and each picker has his own place at a bush.","6"],["No “What is this?” <span class=\"new\">NEW</span>","The boxes no longer carry the “What is this?” button. Help (the ?) still answers everything.","15"],["Wars won and generals <span class=\"new\">NEW</span>","Beating off a raid or defeating a rival is a war won. A soldier with 7 or more stars is a general; at 10 he is a five-star general.","6, 11, 14"],["Stronger raids <span class=\"new\">NEW</span>","A Medium raid is much stronger than an Easy one, and a Hard raid the strongest: more raiders, each hitting harder and taking more blows.","1, 14"],["Berserkers for everyone <span class=\"new\">NEW</span>","Every faction can train berserkers now. Psychana’s are still the ones who move unseen in small bands.","3, 6"],["Add fills a formation <span class=\"new\">NEW</span>","Choose a group and tap Add on the diamond: every soldier you train while Add is on marches to the group and takes his place in its formation.","5"],["The troop diamond <span class=\"new\">NEW</span>","All troop orders sit in one diamond at the bottom left: move, formation, patrol, guard, add, stop and the choosing buttons.","5"],["Formations <span class=\"new\">NEW</span>","Seven shapes (Free, Line, Column, Wedge, Square, Circle, Loose). Soldiers march together at the pace of the slowest.","5, 7"],["Tap to close <span class=\"new\">NEW</span>","One tap puts away a hint, a message or the Art of War advice. A double tap on any box closes it.","5, 15"],["Phones show pictures <span class=\"new\">NEW</span>","On a phone the top bar and the tabs show pictures and numbers; the names show when you tap.","5"],["The Help screen <span class=\"new\">NEW</span>","Search in plain words, 96 short articles with pictures, the whole of this guide, and a Topics drop-down when you tap the ?.","15"],["One guide <span class=\"new\">NEW</span>","The Troop Controls Guide from Phase 4E is part of this guide now (section 5).","5"],["The trophy, with the numbers <span class=\"new\">NEW</span>","Ticks for what is done, crosses for what is not, and every stage’s numbers printed in this guide for each difficulty.","4"],["Saved games to a file <span class=\"new\">NEW</span>","Named saves, an automatic save, and a save you can keep as a file and load again on another device.","15"],["The flat view <span class=\"new\">NEW</span>","The V key (or Settings) switches between the 3D view and a flat map view.","13"],["Soldiers come back <span class=\"new\">NEW</span>","A soldier who runs after an enemy by himself turns back after a set distance instead of following him home.","7"],["Mourning <span class=\"new\">NEW</span>","When your people die, the town mourns for two minutes, and the mood box says so.","10"],["Rivals’ own growth <span class=\"new\">NEW</span>","The rivals grow by their own table, printed in this guide.","14"],["Pictures of every screen <span class=\"new\">NEW</span>","Version 2 had none of the game screens and boxes. Version 3 shows them all.","all"]]}],"summary":"Longer peace NEW, Calling citizens NEW, Which building is asking NEW…"},{"id":"g-read-where-version-2-and-the-game-now-differ","cat":"guide","sec":"read","secTitle":"How to read this guide","title":"Where version 2 and the game now differ","pic":"i:book","blocks":[{"t":"p","h":"These places in version 2 no longer match the game. Version 3 says what the game does now, and each place is marked CORRECTED."},{"t":"table","head":["Version 2 said","The game now","Section"],"rows":[["About five minutes of peace (six on Easy).","10 minutes on Easy and Medium, 5 on Hard (your Phase 4F decision).","1, 2"],["Open Settings and press Fix for a glitching person or building.","The Fix button over people was taken out (your Phase 4C decision). A stuck building still has <b>Remove &amp; rebuild</b> in its own box. For a stuck person, tell Claude Code.","2, 15"],["Double-click selects everyone of that kind on the screen.","Double-click opens the person’s box (your Phase 4C decision). Use the Soldiers, Citizens and Everyone buttons on the diamond to choose many.","5"],["Ladder men climb walls beside the ram.","There are no ladder men in the game.","4, 6"],["At stage 5 every tower comes armed with a ballista or trebuchet.","You buy each tower’s engine (ballista or trebuchet). The rivals buy theirs by themselves.","4, 7"],["Armoured swordsmen need two spike strikes.","Your decision after Phase 4C: everyone dies at one strike except knights, berserkers and mounted knights, who take two.","6, 7"],["Globes: North America, Asia, South America, Australia.","Russia top left, the United States top right, Australia bottom left, South America bottom right.","13"],["The trophy shows the word MET.","It shows a tick for done and a cross for not yet.","4"],["Stage numbers are not printed because they are being tuned.","They are printed here, for Easy, Medium and Hard. The trophy still shows the live numbers.","4"],["The People tab is a button at the bottom left.","It is the face on the corner of the troop diamond, still at the bottom left.","5, 11"],["A second citizen cannot be bought.","Citizens can now be called with the Citizen button (Phase 4F).","11"]]}],"summary":"These places in version 2 no longer match the game. Version 3 says what the game does now, and each place…"},{"id":"g-1-the-goal-and-how-a-game-starts","cat":"guide","sec":"s1","secTitle":"1. The Goal and How a Game Starts","title":"The Goal and How a Game Starts","pic":"i:start","blocks":[{"t":"p","h":"<i>Build a castle. Survive the raids. Destroy every rival who comes against you.</i>"}],"summary":"Build a castle. Survive the raids. Destroy every rival who comes against you."},{"id":"g-1-what-the-game-is","cat":"guide","sec":"s1","secTitle":"1. The Goal and How a Game Starts","title":"What the game is","pic":"i:start","blocks":[{"t":"p","h":"Stronghold Destroyer is a castle-building strategy game that runs in a web browser, on an iPad, a phone or a computer. You pick a faction, build a town, grow a castle, train an army, and fight rivals who are doing the same thing."}],"summary":"Stronghold Destroyer is a castle-building strategy game that runs in a web browser, on an iPad, a phone or…"},{"id":"g-1-how-you-win-and-how-you-lose","cat":"guide","sec":"s1","secTitle":"1. The Goal and How a Game Starts","title":"How you win and how you lose","pic":"i:start","blocks":[{"t":"table","head":["","The rule"],"rows":[["<b>You win</b>","Every rival who is against you has lost his keep. A trading friend does not have to fall. (Build)"],["<b>You lose</b>","Your keep is destroyed, or all your people are gone and there is no food left to make more."],["<b>Peace time</b> <span class=\"new fx\">CORRECTED</span>","<b>10 minutes of peace on Easy and Medium, 5 on Hard</b>, before the first raid. The bandits wait as long. The banner at the start says how long. Use it to gather wood, stone, iron and food, build homes, workshops, farms, walls and towers, and train soldiers. (Set)"],["<b>Raids</b>","Rivals send raids from different directions, each one larger, later with battering rams, catapults and ballistas. Rams and siege engines only come with a large army, never with a few riders. Each enemy rival’s first raid comes about a minute and a quarter after the one before. A Medium raid is much stronger than an Easy one, and a Hard raid the strongest (section 14). ${NEW}"]]}],"summary":"You win, You lose, Peace time CORRECTED…"},{"id":"g-1-setting-up-a-match","cat":"guide","sec":"s1","secTitle":"1. The Goal and How a Game Starts","title":"Setting up a match","pic":"i:start","blocks":[{"t":"p","h":"Before a game begins you choose these things. You are never forced into four rivals."},{"t":"table","head":["Choice","Options"],"rows":[["Your faction","Cy Young, Ticanologue, Hekaranok or Psychana. See section 3."],["Number of rivals","1, 2, 3 or 4. The maximum is 4. The game does not start with four by default."],["Which factions fight you","You pick them, or leave it random."],["Trading friend","If there are two or more rivals, one of them can be a trading friend."],["Difficulty","Easy, Medium or Hard. It tunes how fast the rivals grow, how much your castle stages ask (section 4), and the peace time: 10, 10 or 5 minutes."],["Your start spot","Random by default. You can also choose one."],["Load a saved game <span class=\"new\">NEW</span>","A button on the front page opens your saved games (section 15)."]]}],"summary":"Before a game begins you choose these things. You are never forced into four rivals."},{"id":"g-1-how-every-game-begins","cat":"guide","sec":"s1","secTitle":"1. The Goal and How a Game Starts","title":"How every game begins","pic":"i:start","blocks":[{"t":"cards","items":[{"pic":"u:king","n":"Your king","line":"","d":"A knight who has just been made king."},{"pic":"u:civ","n":"Your citizens","line":"","d":"A few civilians to start the work."},{"pic":"b:house","n":"A house","line":"","d":"A shack in the woods."},{"pic":"b:woodhut","n":"A woodcutter’s hut","line":"","d":"Wood comes first."}]},{"t":"ul","items":["You start with a knight who has just been made king, a few civilians, a shack in the woods and a small wooden palisade. You have wood and food only, and no soldiers other than the king. (Set)","Your start position is different each game, and so is each rival’s. No one starts in the same place every time and no one starts trapped in trees. (Set)","The map is large but not endless, with room for every faction to grow. You cannot see where the rivals’ camps are. See fog of war in section 13.","The castle then grows by itself through five stages. See section 4."]}],"summary":"Your king, Your citizens, A house, A woodcutter’s hut"},{"id":"g-2-stuck-start-here","cat":"guide","sec":"s2","secTitle":"2. Stuck? Start Here","title":"Stuck? Start Here","pic":"i:book","blocks":[{"t":"p","h":"<i>The common problems, what to do about each, and a few Art of War ideas for winning.</i>"},{"t":"p","h":"If you are lost, read this section first. Find your problem in the left column and do what the right column says. Tap and hold on any person to hear what he needs. That one habit solves most problems. The Help screen (the ? at the top) answers questions typed in plain words."}],"summary":"The common problems, what to do about each, and a few Art of War ideas for winning."},{"id":"g-2-your-first-ten-minutes","cat":"guide","sec":"s2","secTitle":"2. Stuck? Start Here","title":"Your first ten minutes","pic":"i:book","blocks":[{"t":"p","h":"This is a suggested order, not a rule. You have <b>10 minutes of peace on Easy and Medium, 5 on Hard</b>, before the first raid. <span class=\"new fx\">CORRECTED</span>"},{"t":"cards","items":[{"pic":"b:house","n":"1. Houses","line":"","d":"Your workers come from them."},{"pic":"b:woodhut","n":"2. Woodcutters","line":"","d":"Wood feeds everything you build."},{"pic":"b:wheatfarm","n":"3. Field","line":"","d":"Wheat for bread and ale; corn to eat."},{"pic":"b:farm","n":"4. Farm","line":"","d":"Animals: eggs, milk and meat."},{"pic":"b:alehouse","n":"5. Alehouse","line":"","d":"Cheer your people."},{"pic":"b:poleturner","n":"6. Spear-maker","line":"","d":"Spears for your first soldiers."},{"pic":"b:wall","n":"7. Wall and gate","line":"","d":"Close the way in."},{"pic":"b:gtower","n":"8. Tower","line":"","d":"On the side the king warns you about."}]},{"t":"ul","items":["<b>Houses first.</b> Each house raises a new citizen every few minutes, and your workers come from them.","<b>Need people faster?</b> Call a citizen with the Citizen button in the Town list. It costs food and gold, and he walks in when his wait is over (section 11). <span class=\"new\">NEW</span>","<b>Wood, then food.</b> Woodcutters feed everything you build. Add a field (put people on corn and wheat) and a farm so you never run out of food.","<b>Cheer your people</b> with an alehouse, and arm a few spearmen from the spear-maker.","<b>Wall and gate, then a tower</b> toward the side the king warns you about. Put a <b>spike pit</b> where raiders will walk, and a <b>water pot</b> near your buildings.","<b>Tap the trophy</b> under the settings button to see what the next stage needs."]}],"summary":"This is a suggested order, not a rule. You have 10 minutes of peace on Easy and Medium, 5 on Hard , before…"},{"id":"g-2-problems-and-what-to-do","cat":"guide","sec":"s2","secTitle":"2. Stuck? Start Here","title":"Problems and what to do","pic":"i:book","blocks":[{"t":"table","head":["The problem","What to do"],"rows":[["People are standing around doing nothing","Idle citizens go to the campfire. Make sure each workplace is built and staffed (one citizen runs a building). Open the <b>People tab</b> (the face on the troop diamond) to see what everyone is doing, then press and hold one person to hear what he needs."],["I am running out of food","Tap your field and put more people on corn (it feeds people straight away), and build a farm. Keep your people happy: happy people grow food faster. At stage 2 build a mill; at stage 3 it comes with five bakeries. If the granary is full, expand it at stage 3 or sell the extra, because too much food brings bugs and disease."],["My people are unhappy or leaving","Press and hold one person: the box says <b>why</b>. Tap Mood at the top for every reason. Usual fixes: ale at a fair price, a house of prayer, a garden, lower taxes, more kinds of food, less crowding, and care for the sick (apothecary or house of prayer)."],["Happiness fell and I do not know why <span class=\"new\">NEW</span>","If your people or soldiers were killed, the town mourns for two minutes. The mood box lists it. It passes by itself."],["I need more people now <span class=\"new\">NEW</span>","Tap the Citizen button in the Town list (key 1). Its label (touch it, or rest the mouse on it) shows what one costs and how long he takes. Happier people come sooner and cheaper. You need room in your houses."],["The castle will not grow to the next stage","Tap the trophy under the settings button. It lists each requirement with what you have and what you need, and says what to do next. The numbers for each difficulty are in section 4."],["Raiders keep breaking in","The king calls out the direction they come from. Put a wall, a gate, a tower, spikes and archers on that side. Add a moat at stage 2, a patrol or Guard order, and archers on a high wall reached by stairs."],["I cannot find the enemy","Fog of war hides rival camps. Longbowmen see twice as far as other soldiers. Explored ground stays revealed. Search or wait for an enemy to show itself."],["My soldiers ran off after an enemy <span class=\"new\">NEW</span>","A soldier who goes after an enemy by himself turns back once he is about a dozen squares from where he started. Soldiers you send stay on your order."],["A building is on fire","The alarm rings and citizens fetch water. Put a water pot near your buildings. Left for ten seconds, half of a building burns."],["I am out of stone or iron","Stone: a quarry beside grey rocks (stage 2, with its ox cart). Iron: an iron mine on the red iron ground (stage 3). Both need wood to build. Growing the castle uses up the stone and iron it asks for."],["A moat is blocking my own people","Citizens, spearmen, swordsmen and flamethrowers can fill a moat. A filled section becomes ground for good, and enemies can cross it too."],["Citizens were killed","They must be replaced. Houses raise new ones every few minutes, and now you can also call one with the Citizen button. <span class=\"new\">NEW</span>"],["A person or building is glitching or walking in circles <span class=\"new fx\">CORRECTED</span>","A building: open its box and tap <b>Remove &amp; rebuild (fix a glitch)</b>; it is rebuilt fresh where it stands, at no cost. A person: the floating Fix button was taken out, so tell Claude Code what happened, and where, so it can be fixed for good."],["Rams are smashing my wall","Rams hurt walls, gates and buildings but cannot hurt soldiers. Stand soldiers at the wall, fight the army that comes with them, and keep archers on the walls. Broken walls repair themselves."],["A panel or a hint is in the way <span class=\"new\">NEW</span>","One tap puts away a hint, a message or the Art of War advice. A double tap (or double click) on any box, away from its buttons, closes it. Every box also has a big X, and Esc closes it."],["I want to keep my game","Settings, then Save. Give it a name. Load or delete saves from the same place, or keep a save as a file (section 15)."]]}],"summary":"People are standing around doing nothing, I am running out of food, My people are unhappy or leaving…"},{"id":"g-2-a-few-art-of-war-ideas","cat":"guide","sec":"s2","secTitle":"2. Stuck? Start Here","title":"A few Art of War ideas","pic":"i:book","blocks":[{"t":"p","h":"The game’s advisor gives tips in the spirit of Sun Tzu’s <i>The Art of War</i>. These are a few of the ideas, in game terms. The in-game hints use their own wording."},{"t":"table","head":["The idea","In the game"],"rows":[["Know yourself and know the enemy","Check the trophy and the People tab before you decide, and find out which faction you face. Each one has a weakness (section 3)."],["Be ready, do not hope","Do not count on the enemy not coming. Spend peace time on towers, walls and spikes, not just on growing."],["Hold the high ground","Archers on walls and towers shoot farther and are harder to reach. Use a high wall with stairs, and a lookout tower."],["Set a bait and a trap","Leave a gap that leads raiders over hidden spikes or a moat. They break themselves before they reach you."],["Strike where he is unprepared","A rival is small early. Raid his farms and food before he grows and the game can end in about 15 minutes."],["An army needs supplies","Guard your farms, granary and market. Without food and gold your soldiers cannot be made."],["Win without a siege if you can","Taking a strong wall by force costs the most. Slow a rival’s food and trade instead, and bring rams and flames only with a large army."],["Victory feeds the town <span class=\"new\">NEW</span>","Every war you win brings citizens sooner and cheaper for ten minutes. Keep your veterans alive: generals do the same (section 11)."]]}],"summary":"The game’s advisor gives tips in the spirit of Sun Tzu’s The Art of War . These are a few of the ideas, in…"},{"id":"g-3-the-four-factions","cat":"guide","sec":"s3","secTitle":"3. The Four Factions","title":"The Four Factions","pic":"i:crown","blocks":[{"t":"p","h":"<i>You pick one. The computer rivals play the same four by the same rules.</i>"},{"t":"p","h":"Each faction has one big strength and one real weakness. A weakness can always be used against it. The names are working names and are fine as spelled."}],"summary":"You pick one. The computer rivals play the same four by the same rules."},{"id":"g-3-cy-young-the-bread-makers","cat":"guide","sec":"s3","secTitle":"3. The Four Factions","title":"Cy Young — the bread makers","pic":"i:crown","blocks":[{"t":"line","h":"Strength: food and money"},{"t":"ul","items":["The mill and bakeries make 4 to 5 times the food.","They sell the surplus for money, so they out-buy and out-upgrade everyone.","Weakness: no special power in a fight.","How to beat them: slow them early by raiding their farms and food, before the money snowballs.","Starts with: the king, 5 civilians, 100 food and 80 wood."]}],"parent":"The Four Factions","summary":"Strength: food and money"},{"id":"g-3-ticanologue-the-marketers","cat":"guide","sec":"s3","secTitle":"3. The Four Factions","title":"Ticanologue — the marketers","pic":"i:crown","blocks":[{"t":"line","h":"Strength: trade"},{"t":"ul","items":["Market prices are half of everyone else’s.","Weakness: the market costs a lot to build.","How to beat them: destroy the market. It is the most valuable building they have.","Starts with: the king, 5 civilians, 100 food and 80 wood."]}],"parent":"The Four Factions","summary":"Strength: trade"},{"id":"g-3-hekaranok-the-healers","cat":"guide","sec":"s3","secTitle":"3. The Four Factions","title":"Hekaranok — the healers","pic":"i:crown","blocks":[{"t":"line","h":"Strength: staying alive"},{"t":"ul","items":["Wounded units run home, heal, and return to exactly where they were. A bell recalls them.","Double the population. Stronger abbeys.","Weakness: each person is weaker, and a unit that is killed cannot be healed.","How to beat them: kill units outright instead of wounding them.","Starts with: the king, 10 civilians, 120 food and 80 wood."]}],"parent":"The Four Factions","summary":"Strength: staying alive"},{"id":"g-3-psychana-sight-and-stealth","cat":"guide","sec":"s3","secTitle":"3. The Four Factions","title":"Psychana — sight and stealth","pic":"i:crown","blocks":[{"t":"line","h":"Strength: seeing and sneaking"},{"t":"ul","items":["All units see as far as longbowmen.","Their berserkers can sneak up unseen in small bands (every faction has berserkers, but only Psychana’s move unseen).","Weakness: towers and palisade towers near a castle still spot them.","How to beat them: ring your castle with towers.","Starts with: the king, 5 civilians, 100 food and 80 wood."]}],"parent":"The Four Factions","summary":"Strength: seeing and sneaking"},{"id":"g-3-what-the-front-page-shows","cat":"guide","sec":"s3","secTitle":"3. The Four Factions","title":"What the front page shows","pic":"i:crown","blocks":[{"t":"p","h":"The front page shows all four side by side in large, high-contrast text: the name, the emblem and colors, one plain sentence on how it plays, its strengths, its weakness and its starting setup. Tap one to choose it, then choose how many rivals and the difficulty. All the faction names, descriptions and numbers live in one settings block so they can be tuned in one place. (The front page is pictured in section 1.)"}],"summary":"The front page shows all four side by side in large, high-contrast text: the name, the emblem and colors,…"},{"id":"g-4-the-five-castle-stages","cat":"guide","sec":"s4","secTitle":"4. The Five Castle Stages","title":"The Five Castle Stages","pic":"i:trophy","blocks":[{"t":"p","h":"<i>The castle grows by itself when it is ready. Tap the trophy to see what it needs.</i>"},{"t":"table","head":["Stage","Name","Known for"],"rows":[["<b>1</b>","Shack","spear, archer"],["<b>2</b>","Homestead","longbow, quarry"],["<b>3</b>","Hold","the big jump"],["<b>4</b>","Castle","mounted, siege"],["<b>5</b>","Stronghold","trebuchets"]]}],"summary":"The castle grows by itself when it is ready. Tap the trophy to see what it needs."},{"id":"g-4-what-decides-when-the-castle-grows","cat":"guide","sec":"s4","secTitle":"4. The Five Castle Stages","title":"What decides when the castle grows","pic":"i:trophy","blocks":[{"t":"p","h":"When the requirements for the next stage are met, the castle grows on its own. The requirements combine people, happiness, food, stone, iron and the right buildings standing. You can still add buildings at any time, but you must gather the stone, iron and food to do it."},{"t":"ul","items":["The requirements were lowered in Phase 4D. An Easy game reaches stage 2 early in the first play session. Each later stage takes longer than the one before, and Medium and Hard take longer than Easy. (Build)","The numbers are now printed below, for each difficulty. <span class=\"new fx\">CORRECTED</span> The trophy shows the live numbers.","Growing the castle <b>uses up</b> the stone and iron it asks for. The food has to be in store, and is kept."]}],"summary":"When the requirements for the next stage are met, the castle grows on its own. The requirements combine…"},{"id":"g-4-the-trophy-button","cat":"guide","sec":"s4","secTitle":"4. The Five Castle Stages","title":"The trophy button","pic":"i:trophy","blocks":[{"t":"p","h":"A trophy button sits directly below the settings button on the game screen. It is always there, and it never opens on its own. Tap it and a panel shows what you still need for the next stage: for each requirement, what you have, what you need, and <b>a tick when it is done or a cross when it is not</b> <span class=\"new fx\">CORRECTED</span>, plus one plain sentence on what to do next. It pauses the game like other panels. At the final stage it tells you that you have reached the top. A double tap on the panel closes it <span class=\"new\">NEW</span>."}],"summary":"A trophy button sits directly below the settings button on the game screen. It is always there, and it…"},{"id":"g-4-what-each-stage-needs-by-difficulty","cat":"guide","sec":"s4","secTitle":"4. The Five Castle Stages","title":"What each stage needs, by difficulty","pic":"i:trophy","blocks":[{"t":"p","h":"Read across: what your castle needs to grow <i>into</i> that stage. Stone and iron are used up when it grows. The buildings must be standing and finished."},{"t":"h","h":"Easy"},{"t":"table","head":["Stage","People","Happy","Food","Stone","Iron","Buildings standing"],"rows":[["<b>2. Homestead</b>","8","35","80","—","—","2 houses, 1 woodcutter's huts, 1 farms or fields"],["<b>3. Hold</b>","16","40","200","100","—","4 houses, 1 quarries, 1 taverns"],["<b>4. Castle</b>","30","45","250","360","70","1 blacksmiths, 1 markets, 1 mills, 1 bakeries"],["<b>5. Stronghold</b>","42","50","400","720","210","1 school, 2 stone towers, 1 church"]]},{"t":"h","h":"Medium"},{"t":"table","head":["Stage","People","Happy","Food","Stone","Iron","Buildings standing"],"rows":[["<b>2. Homestead</b>","9","38","92","—","—","2 houses, 1 woodcutter's huts, 1 farms or fields"],["<b>3. Hold</b>","19","43","270","135","—","5 houses, 1 quarries, 1 taverns"],["<b>4. Castle</b>","38","48","387","558","108","1 blacksmiths, 1 markets, 1 mills, 1 bakeries"],["<b>5. Stronghold</b>","58","53","700","1260","368","1 school, 3 stone towers, 1 church"]]},{"t":"h","h":"Hard"},{"t":"table","head":["Stage","People","Happy","Food","Stone","Iron","Buildings standing"],"rows":[["<b>2. Homestead</b>","9","41","104","—","—","2 houses, 1 woodcutter's huts, 1 farms or fields"],["<b>3. Hold</b>","22","46","340","170","—","5 houses, 1 quarries, 1 taverns"],["<b>4. Castle</b>","47","51","525","756","147","1 blacksmiths, 1 markets, 1 mills, 1 bakeries"],["<b>5. Stronghold</b>","74","56","1000","1800","525","1 school, 4 stone towers, 1 church"]]}],"summary":"Read across: what your castle needs to grow into that stage. Stone and iron are used up when it grows. The…"},{"id":"g-4-what-each-stage-brings","cat":"guide","sec":"s4","secTitle":"4. The Five Castle Stages","title":"What each stage brings","pic":"i:trophy","blocks":[{"t":"table","head":["Stage","What comes in"],"rows":[["<b>1. Shack</b>","Spearmen and archers. Houses, farms and fields. Woodcutter’s huts. The alehouse, fletcher, spear-maker and armory. Wooden walls, gate, towers, spike pits and water pots."],["<b>2. Homestead</b>","Longbowmen (a separate unit, not an upgrade). Stone quarries with ox carts. The tavern, brewery and hop farm. High walls and stairs, lookout towers and moats. The mill, house of prayer, apothecary and stocks."],["<b>3. Hold</b>","The big jump. Swordsmen, macemen, crossbowmen, berserkers and foot knights. Ballistas. The stable, blacksmith and iron mine. The school, market, church, engineer’s hut and stone tower. Bakeries (five to a mill). Vineyard and orchard. Granary expansion. Escorted work groups. The feast."],["<b>4. Castle</b> <span class=\"new fx\">CORRECTED</span>","Mounted knights. Rams, flamethrowers and catapults. The abbey. Round and great towers, which come empty: you buy the ballista or trebuchet for each."],["<b>5. Stronghold</b> <span class=\"new fx\">CORRECTED</span>","Trebuchets, including mobile trebuchets. You buy a ballista or trebuchet for each giant tower (the rivals buy theirs by themselves). A school is required first. Wars are longer and harder, and people are not easily killed."]]}],"summary":"1. Shack, 2. Homestead, 3. Hold…"},{"id":"g-4-what-happens-when-the-castle-grows","cat":"guide","sec":"s4","secTitle":"4. The Five Castle Stages","title":"What happens when the castle grows","pic":"i:trophy","blocks":[{"t":"ul","items":["The footprint grows 2 to 3 blocks in every direction and clears the trees and rocks in the way.","Materials upgrade: wood, then brick, then stone, then thicker stone. Buildings, walls and towers grow with the castle.","Your buildings inside the new footprint move inside the new walls automatically. Nothing is lost.","The side buttons and lists change at each stage, so only what is available at that stage can be bought or built."]}],"summary":"The footprint grows 2 to 3 blocks in every direction and clears the trees and rocks in the way."},{"id":"g-5-controls-and-buttons","cat":"guide","sec":"s5","secTitle":"5. Controls and Buttons","title":"Controls and Buttons","pic":"i:diamond","blocks":[{"t":"p","h":"<i>Every key, tap and button, and what it does.</i>"}],"summary":"Every key, tap and button, and what it does."},{"id":"g-5-the-game-screen","cat":"guide","sec":"s5","secTitle":"5. Controls and Buttons","title":"The game screen","pic":"i:diamond","blocks":[{"t":"ul","items":["<b>1. Settings (the gear)</b> — Help, the views, sound, voice, saves, Quit. Next to it: ? for Help, and Pause.","<b>2. The top bar</b> — Your faction, food, wood, stone, gold, people (and room), happiness, taxes, rivals, soldiers, goods, the season and weather, the wind.","<b>3. The trophy</b> — What the next castle stage needs (section 4).","<b>4. The Art of War advisor</b> — One tip at a time; tap it to put it away.","<b>5. The command panel</b> — The five lists: Town, Castle, Army, Rule and Industry (keys 1 to 5). Hide it with Tab.","<b>6. The troop diamond</b> — Every order for your soldiers (see below).","<b>7. The map</b> — Tap or drag it to move the view.","<b>8. Happiness</b> — Tap for every reason your people are happy or not.","<b>9. The People tab</b> — Everyone at a glance (section 11)."]}],"summary":"1. Settings (the gear) — Help, the views, sound, voice, saves, Quit. Next to it: ? for Help, and Pause."},{"id":"g-5-the-camera","cat":"guide","sec":"s5","secTitle":"5. Controls and Buttons","title":"The camera","pic":"i:diamond","blocks":[{"t":"p","h":"The game is a true 3D world seen from one fixed three-quarter angle that looks like an isometric view. There is no camera twist or tilt. You can zoom and scroll. Mouse-edge scrolling is slow, smooth and predictable. The flat view stays, and the V key switches between the two views (section 13)."}],"summary":"The game is a true 3D world seen from one fixed three-quarter angle that looks like an isometric view.…"},{"id":"g-5-mouse-and-keyboard","cat":"guide","sec":"s5","secTitle":"5. Controls and Buttons","title":"Mouse and keyboard","pic":"i:diamond","blocks":[{"t":"table","head":["Input","What it does"],"rows":[["Left-click","Select a person or building. With soldiers chosen, a click on the ground sends them there."],["Drag a box","Select several units. Improved for large armies."],["Double-click <span class=\"new fx\">CORRECTED</span>","Opens the person’s box (his work, his happiness, his worries). To choose many at once, use the Soldiers, Citizens or Everyone buttons on the diamond."],["Right-click","Give an order: move, gather, build, attack, climb a wall, deposit goods."],["Mouse wheel","Zoom."],["Arrow keys or screen edge","Scroll the map."],["1 to 5","Open the side lists: Town, Castle, Army, Rule, Industry."],["H","Help."],["P","Pause."],["Space","Return to your castle."],["R or T","Turn a building while placing it."],["V","Switch between the 3D and flat views."],["M","Sound on or off."],["S","Stop the selected units."],["Z","Put a workshop to sleep (Z again wakes it)."],["Esc","Cancel, or close the open box."],["Tab","Hide the side panel."]]}],"summary":"Left-click, Drag a box, Double-click CORRECTED…"},{"id":"g-5-touch-ipad-and-phone","cat":"guide","sec":"s5","secTitle":"5. Controls and Buttons","title":"Touch (iPad and phone)","pic":"i:diamond","blocks":[{"t":"ul","items":["Tap to select. Tap the ground or a target to command.","One finger scrolls. Two fingers zoom.","Quick tap on a person shows a small glance. Press and hold for a second or two for the full story (section 11).","<b>One tap</b> on a hint, a message or the Art of War advice puts it away; the next one comes later. <b>A double tap</b> on any box, away from its buttons, closes it: the mood box, the trophy, Settings, Help, the People tab and the building boxes. One tap on a box does not close it, and its buttons still work. <span class=\"new\">NEW</span>","Every pop-up box also has a big X. The game pauses while you read a panel or menu, unless enemies are close."]}],"summary":"Tap to select. Tap the ground or a target to command."},{"id":"g-5-the-troop-diamond","cat":"guide","sec":"s5","secTitle":"5. Controls and Buttons","title":"The troop diamond","pic":"i:diamond","blocks":[{"t":"p","h":"All the troop orders sit in one diamond at the bottom left of the screen, on a computer, an iPad and a phone. Choose soldiers first (tap one, draw a box round several, or tap the crossed swords to choose them all), then use the diamond. Touch any button, or hover over it with the mouse, to see its name. With nobody chosen the order buttons are dimmed, and a dimmed button says why. The green number on the middle button is how many are chosen."},{"t":"table","head":["","Button","What it does"],"rows":[["1–4","Move up, right, down, left","The chosen soldiers walk a short way that way."],["5","Formation","Choose a shape, then send them anywhere (see below)."],["6","Patrol","Then draw the route with your finger or the mouse."],["7","Guard","Then tap the place they should hold."],["8","Add","Tap more soldiers to add them to the group, and every soldier you train while Add is on marches to join its formation (tap Add again to stop). <span class=\"new\">NEW</span>"],["9","Stop","Stop where they are."],["10","People","Your people: who they are, their work and their worries (section 11)."],["11","Soldiers","Choose all your soldiers."],["12","Castle","Back to your castle (Space)."],["13","Let go","Let go of the chosen people."],["14","Everyone","Choose everyone."],["15","Citizens","Choose all your citizens."]]}],"summary":"All the troop orders sit in one diamond at the bottom left of the screen, on a computer, an iPad and a…"},{"id":"g-5-formations","cat":"guide","sec":"s5","secTitle":"5. Controls and Buttons","title":"Formations","pic":"i:diamond","blocks":[{"t":"p","h":"Tap the two walking soldiers in the middle of the diamond: the formations open above it. Choose one and the chosen soldiers form up where they stand; then tap the ground and they march there in that shape. Any number works, from 3 to 30 or more."},{"t":"ul","items":["Tap the ground with soldiers chosen and they march there in the formation you chose (or in a neat block when the formation is Free).","They march at the pace of the slowest, so they arrive together, and stand facing the way they went.","Soldiers in a formation stay in it until you give them a new order, and they are not taken for other duties.","Free is the old way: a neat block with no set shape.","<b>To fill a formation as you train:</b> choose the group and tap Add on the diamond. Every soldier you train while Add is on marches to the group and takes his place, and the group closes up round him in the same shape, where it stands. Tap Add again and new soldiers go to the rally flag as before. <span class=\"new\">NEW</span>"]},{"t":"p","h":"Each picture: ten soldiers (spearmen, with a bowman in every five), seen from above in the flat view, after marching up the page."}],"summary":"Tap the two walking soldiers in the middle of the diamond: the formations open above it. Choose one and…"},{"id":"g-5-the-buttons-on-the-screen","cat":"guide","sec":"s5","secTitle":"5. Controls and Buttons","title":"The buttons on the screen","pic":"i:diamond","blocks":[{"t":"table","head":["Button","What it does"],"rows":[["Settings icon (a gear)","Settings. It replaces the word “Menu”. Help, the views, sound, voice, Save and Load, and Quit Game are inside it."],["Question mark (?)","Help. Search it for a word or an activity, and read the pictures (section 15)."],["Trophy","Directly below the settings button. Shows what the next castle stage needs."],["People tab <span class=\"new fx\">CORRECTED</span>","The face on the corner of the troop diamond, at the bottom left. Opens the people panel (section 11)."],["Side lists 1 to 5","Town, Castle, Army, Rule and Industry. Each holds picture buttons."],["Picture buttons","About one inch square, a big picture, a small count badge in the corner, and the name when you tap or hover."],["Rally flags","Three kinds: a flag beside a shield for soldiers, a flag beside a person for citizens, a flag beside a siege weapon for siege."],["Patrol and Guard <span class=\"new\">NEW</span>","Now on the troop diamond. Draw a patrol route with a mouse or finger, or tell soldiers to Guard an area."],["Stage chip <span class=\"new\">NEW</span>","Taken off the top bar: the trophy shows the stage."]]}],"summary":"Settings icon (a gear), Question mark (?), Trophy…"},{"id":"g-5-on-a-phone","cat":"guide","sec":"s5","secTitle":"5. Controls and Buttons","title":"On a phone","pic":"i:diamond","blocks":[{"t":"ul","items":["The item lists sit at the bottom of the screen and open upward.","The panel closes by itself after you pick an item, so you can drag the chosen object into place without the panel covering the battlefield.","The detail box for a person slides up along the bottom of the screen.","<b>Pictures instead of words</b> <span class=\"new\">NEW</span>: the top bar shows the faction’s shield, food, wood, stone, gold, people, happiness (a number) and taxes (dots). The tabs show their pictures. A name shows when you tap a button or it is chosen. This saves room on the small screen.","The same troop diamond sits above the five list tabs. The people count reads like 12/15 (people, and room for them), and taxes show as dots: none, one or two."]}],"summary":"The item lists sit at the bottom of the screen and open upward."},{"id":"g-5-placing-buildings-and-walls","cat":"guide","sec":"s5","secTitle":"5. Controls and Buttons","title":"Placing buildings and walls","pic":"i:diamond","blocks":[{"t":"ul","items":["Turn a building before you place it, and place it facing toward or away from you. Drag and drop works with a mouse and with touch.","Walls, fences and gates follow the exact route you draw. They do not reroute around trees, rocks or food. Obstacles in the way are cleared or split. Your intentional gate openings stay."]}],"summary":"Turn a building before you place it, and place it facing toward or away from you. Drag and drop works with…"},{"id":"g-6-units-and-soldiers","cat":"guide","sec":"s6","secTitle":"6. Units and Soldiers","title":"Units and Soldiers","pic":"u:spear","blocks":[{"t":"p","h":"<i>Every person and soldier: the stage it arrives, how it moves, how it fights, how it grows.</i>"},{"t":"p","h":"Units fight on their own when an enemy comes near, or when you order them. Each attack is a timed swing, and the damage lands at a set moment in the swing. Each picture is the unit as the game draws it today. Speed numbers live in the game settings and are not printed here."}],"summary":"Every person and soldier: the stage it arrives, how it moves, how it fights, how it grows."},{"id":"g-6-citizen","cat":"guide","sec":"s6","secTitle":"6. Units and Soldiers","title":"Citizen","pic":"u:civ","blocks":[{"t":"line","h":"Stage 1 · your workers"},{"t":"ul","items":["<b>Does:</b> builds, fetches wood, food and stone, and staffs every workplace.","<b>Moves:</b> walks between home, work and the campfire. Takes 20 to 30 second breaks at a fire, a house, the tavern or the House of Prayer. Stays near the castle.","<b>Grows:</b> new citizens grow up in your houses. Education at the school makes them put out fires and repair faster.","<b>Called:</b> you can call more from the countryside with the Citizen button (section 11). <span class=\"new\">NEW</span>","Can fill a moat in."]}],"parent":"Your people","summary":"Stage 1 · your workers"},{"id":"g-6-your-king","cat":"guide","sec":"s6","secTitle":"6. Units and Soldiers","title":"Your king","pic":"u:king","blocks":[{"t":"line","h":"Stage 1 · your leader"},{"t":"ul","items":["<b>Does:</b> the only fighter you start with. Strong, and worth guarding. He stands on the keep, spots enemies farther than an archer can shoot, and warns you which way they come.","<b>Moves:</b> on foot, and stays at your castle.","Takes only a quarter of the damage from ordinary weapons."]}],"parent":"Your people","summary":"Stage 1 · your leader"},{"id":"g-6-spearman","cat":"guide","sec":"s6","secTitle":"6. Units and Soldiers","title":"Spearman","pic":"u:spear","blocks":[{"t":"line","h":"Stage 1 · needs a spear and 10 gold"},{"t":"ul","items":["<b>Does:</b> cheap, quick foot soldier with a long reach. Escorts work groups.","<b>Moves:</b> quick on foot. Can fill a moat in."]}],"parent":"Foot soldiers","summary":"Stage 1 · needs a spear and 10 gold"},{"id":"g-6-archer","cat":"guide","sec":"s6","secTitle":"6. Units and Soldiers","title":"Archer","pic":"u:archer","blocks":[{"t":"line","h":"Stage 1 · needs a bow and 10 gold"},{"t":"ul","items":["<b>Does:</b> shoots from a distance. Best on walls and towers, where it shoots farther and is hard to reach.","<b>Moves:</b> on foot, and climbs high walls by the stairs. Can hit flamethrowers, but slowly, about one at a time."]}],"parent":"Foot soldiers","summary":"Stage 1 · needs a bow and 10 gold"},{"id":"g-6-longbowman","cat":"guide","sec":"s6","secTitle":"6. Units and Soldiers","title":"Longbowman","pic":"u:archer.longbow","blocks":[{"t":"line","h":"Stage 2 · a separate unit, not an upgrade · needs a bow and 15 gold"},{"t":"ul","items":["<b>Does:</b> shoots farther and sees <b>twice as far</b> as other soldiers. Every lookout tower gets one at the top.","Cannot hit the fast flamethrowers."]}],"parent":"Foot soldiers","summary":"Stage 2 · a separate unit, not an upgrade · needs a bow and 15 gold"},{"id":"g-6-crossbowman","cat":"guide","sec":"s6","secTitle":"6. Units and Soldiers","title":"Crossbowman","pic":"u:archer.crossbow","blocks":[{"t":"line","h":"Stage 3 · needs a bow, 2 iron and 15 gold"},{"t":"ul","items":["<b>Does:</b> slow but heavy bolts. A bolt can strike a mounted knight’s rider past his horse.","A separate unit from the archer and the longbowman; you can keep a mix of all three.","Cannot be killed by a flamethrower’s knife."]}],"parent":"Foot soldiers","summary":"Stage 3 · needs a bow, 2 iron and 15 gold"},{"id":"g-6-swordsman","cat":"guide","sec":"s6","secTitle":"6. Units and Soldiers","title":"Swordsman","pic":"u:sword","blocks":[{"t":"line","h":"Stage 3 · needs a sword and 10 gold"},{"t":"ul","items":["<b>Does:</b> steady, well-armoured fighter for close combat.","Dies from one spike strike, like most soldiers (your decision after Phase 4C). <span class=\"new fx\">CORRECTED</span> Can fill a moat in."]}],"parent":"Foot soldiers","summary":"Stage 3 · needs a sword and 10 gold"},{"id":"g-6-maceman","cat":"guide","sec":"s6","secTitle":"6. Units and Soldiers","title":"Maceman","pic":"u:maceman","blocks":[{"t":"line","h":"Stage 3 · needs a mace and 10 gold"},{"t":"ul","items":["<b>Does:</b> heavy hitter in armour, made at the blacksmith from iron."]}],"parent":"Foot soldiers","summary":"Stage 3 · needs a mace and 10 gold"},{"id":"g-6-berserker","cat":"guide","sec":"s6","secTitle":"6. Units and Soldiers","title":"Berserker","pic":"u:maceman.berserker","blocks":[{"t":"line","h":"Stage 3 · every faction · needs a mace, 2 leather and 10 gold"},{"t":"ul","items":["<b>Does:</b> fierce axe fighter. Sees as far as a longbowman. Psychana’s berserkers move unseen in small bands.","Leather comes from the farm’s cows and bulls. Needs two spike strikes to die. Cannot be killed by a flamethrower’s small knife. Cannot fill a moat."]}],"parent":"Foot soldiers","summary":"Stage 3 · every faction · needs a mace, 2 leather and 10 gold"},{"id":"g-6-knight-on-foot","cat":"guide","sec":"s6","secTitle":"6. Units and Soldiers","title":"Knight (on foot)","pic":"u:knight.foot","blocks":[{"t":"line","h":"Stage 3 · needs a sword, armour and 20 gold"},{"t":"ul","items":["<b>Does:</b> hard to hurt. Takes a quarter of the damage from ordinary weapons; only knights, kings, ballistas and trebuchets wound him fully.","Needs two spike strikes to die. Cannot fill a moat."]}],"parent":"Foot soldiers","summary":"Stage 3 · needs a sword, armour and 20 gold"},{"id":"g-6-mounted-knight","cat":"guide","sec":"s6","secTitle":"6. Units and Soldiers","title":"Mounted knight","pic":"u:knight","blocks":[{"t":"line","h":"Stage 4 · a knight plus a horse from the stable"},{"t":"ul","items":["<b>Does:</b> very hard to kill. The horse takes the blows first and must fall, then the rider, unless a crossbowman or a ballista hits the rider directly.","<b>Moves:</b> rides the horse. Cannot fill a moat in."]}],"parent":"Foot soldiers","summary":"Stage 4 · a knight plus a horse from the stable"},{"id":"g-6-flamethrower-squad","cat":"guide","sec":"s6","secTitle":"6. Units and Soldiers","title":"Flamethrower squad","pic":"u:archer.flame","blocks":[{"t":"line","h":"Stage 4 · attack wars only · needs a sword, armour and 20 gold"},{"t":"ul","items":["<b>Does:</b> one click buys a squad of 10 and it does not cost 10 people. It costs about as much as one unmounted knight.","<b>Moves:</b> fast. Longbowmen cannot hit them. A group of 20 is hard for archers to stop.","Their flame hurts but cannot kill. Their real danger is setting buildings on fire, and the people inside burn.","They can fill a moat; they dig moats around themselves in the middle of nowhere. Melee soldiers kill them easily. They never defend and never escort."]}],"parent":"Foot soldiers","summary":"Stage 4 · attack wars only · needs a sword, armour and 20 gold"},{"id":"g-6-battering-ram","cat":"guide","sec":"s6","secTitle":"6. Units and Soldiers","title":"Battering ram","pic":"u:ram","blocks":[{"t":"line","h":"Stage 4 · attack wars only"},{"t":"ul","items":["<b>Does:</b> smashes walls, gates and buildings. It cannot hurt soldiers, so guard it.","Comes only with a large army, never with a few riders. (Version 2 mentioned ladder men beside it; there are none in the game.)"]}],"parent":"Siege engines and carts","summary":"Stage 4 · attack wars only"},{"id":"g-6-catapult","cat":"guide","sec":"s6","secTitle":"6. Units and Soldiers","title":"Catapult","pic":"u:catapult","blocks":[{"t":"line","h":"Stage 4 · siege"},{"t":"ul","items":["<b>Does:</b> lobs heavy stones from far away. Best against walls and towers."]}],"parent":"Siege engines and carts","summary":"Stage 4 · siege"},{"id":"g-6-ballista","cat":"guide","sec":"s6","secTitle":"6. Units and Soldiers","title":"Ballista","pic":"u:ballista","blocks":[{"t":"line","h":"Stage 3 · walking or tower-mounted"},{"t":"ul","items":["<b>Does:</b> a giant crossbow that cuts down soldiers at long range and only chips stone. Hits mounted riders directly and hurts knights fully.","On a tower it sees as far as a longbowman. A tower ballista costs 400 gold and 150 wood. (Build)"]}],"parent":"Siege engines and carts","summary":"Stage 3 · walking or tower-mounted"},{"id":"g-6-trebuchet","cat":"guide","sec":"s6","secTitle":"6. Units and Soldiers","title":"Trebuchet","pic":"u:trebuchet","blocks":[{"t":"line","h":"Stage 5 · mobile or tower-mounted"},{"t":"ul","items":["<b>Does:</b> throws farthest of all. Built by engineers. Needs stage 5 and the school’s top level.","A tower trebuchet costs 800 gold, 300 wood and 100 stone. (Build) Hurts knights fully."]}],"parent":"Siege engines and carts","summary":"Stage 5 · mobile or tower-mounted"},{"id":"g-6-ox-cart","cat":"guide","sec":"s6","secTitle":"6. Units and Soldiers","title":"Ox cart","pic":"u:oxcart","blocks":[{"t":"line","h":"Stage 2 · comes free with each quarry"},{"t":"ul","items":["<b>Does:</b> hauls cut stone from a quarry to your stores. Oxen carry ore and stone; going from one ox to two is automatic."]}],"parent":"Siege engines and carts","summary":"Stage 2 · comes free with each quarry"},{"id":"g-6-engineer","cat":"guide","sec":"s6","secTitle":"6. Units and Soldiers","title":"Engineer","pic":"u:engineer","blocks":[{"t":"line","h":"Stage 3 · needs an engineer’s hut and school training"},{"t":"ul","items":["<b>Does:</b> repairs buildings very fast and works faster as it learns. Builds and crews siege engines, and builds trebuchets at stage 5."]}],"parent":"Siege engines and carts","summary":"Stage 3 · needs an engineer’s hut and school training"},{"id":"g-6-how-a-soldier-grows-veteran-stars","cat":"guide","sec":"s6","secTitle":"6. Units and Soldiers","title":"How a soldier grows: veteran stars","pic":"u:spear","blocks":[{"t":"ul","items":["Every soldier who survives a battle earns a star above his head when selected. Each further battle adds another, even up to a hundred, shown as a cluster.","Star colors change to greater, lighter colors as he advances. Each star makes him stronger.","A plain spearman can end up as fast and strong as a mounted knight without a horse. Every soldier can become important.","A quick tap shows his stars, level and education. Press and hold shows his full record, including how many wars he has fought."]}],"summary":"Every soldier who survives a battle earns a star above his head when selected. Each further battle adds…"},{"id":"g-6-generals","cat":"guide","sec":"s6","secTitle":"6. Units and Soldiers","title":"Generals","pic":"u:spear","blocks":[{"t":"ul","items":["A soldier with <b>7 or more stars</b> is a <b>general</b>, and at <b>10 stars</b> a <b>five-star general</b>. A banner announces each, and his box says “a general” or “a five-star general”. (Your decision after version 3; the numbers are one setting each.)","Generals in the field or in the camp encourage the countryside: each general (up to 3) makes a called citizen come sooner and cost a little less, and makes the houses raise their children sooner (section 11).","So keep your veterans alive: a general lost is felt in the town as well as on the field."]}],"summary":"A soldier with 7 or more stars is a general , and at 10 stars a five-star general . A banner announces…"},{"id":"g-6-how-a-soldier-grows-education","cat":"guide","sec":"s6","secTitle":"6. Units and Soldiers","title":"How a soldier grows: education","pic":"u:spear","blocks":[{"t":"p","h":"Once the school is built it has a soldiers button that educates all soldiers together. Up to level 5 they get smarter, harder to kill, and heal and repair faster. It works through hidden numbers, so they may look the same. Stars and education stack, so a soldier who survives many battles can become super strong."}],"summary":"Once the school is built it has a soldiers button that educates all soldiers together. Up to level 5 they…"},{"id":"g-6-the-soldiers-as-designed","cat":"guide","sec":"s6","secTitle":"6. Units and Soldiers","title":"The soldiers as designed","pic":"u:spear","blocks":[{"t":"p","h":"These are the design-sheet pictures of the soldiers and engines. The game pictures above are the same units as they appear in play."}],"summary":"These are the design-sheet pictures of the soldiers and engines. The game pictures above are the same…"},{"id":"g-6-lookouts-and-the-keep","cat":"guide","sec":"s6","secTitle":"6. Units and Soldiers","title":"Lookouts and the keep","pic":"u:spear","blocks":[{"t":"ul","items":["Every lookout tower automatically gets a sentry at the door, plus a longbowman and a regular archer at the top, for every faction.","Your keep is the heart of the castle. It grows through the five stages and shoots at enemies who come near."]}],"summary":"Every lookout tower automatically gets a sentry at the door, plus a longbowman and a regular archer at the…"},{"id":"g-7-combat-and-defenses","cat":"guide","sec":"s7","secTitle":"7. Combat and Defenses","title":"Combat and Defenses","pic":"b:gtower","blocks":[{"t":"p","h":"<i>Walls, gates, moats, spikes, towers, patrols and how a battle plays.</i>"}],"summary":"Walls, gates, moats, spikes, towers, patrols and how a battle plays."},{"id":"g-7-walls-and-gates","cat":"guide","sec":"s7","secTitle":"7. Combat and Defenses","title":"Walls and gates","pic":"b:gtower","blocks":[{"t":"cards","items":[{"pic":"b:wall","n":"Wall","line":"Stage 1 · 8 wood","d":"Draw it from point to point; it grows from wood to stone with the castle."},{"pic":"b:gate","n":"Gate","line":"Stage 1 · 15 wood","d":"Lets your people through a wall and keeps enemies out."},{"pic":"b:highwall","n":"High Wall","line":"Stage 2 · 6 stone","d":"Stone wall as tall as the keep; archers climb it by stairs."},{"pic":"b:stairs","n":"Stairs","line":"Stage 2 · 4 stone","d":"Placed beside a high wall so archers can climb it."}]},{"t":"p","h":"Walls begin as a wooden palisade and turn to brick as the castle grows. The picture below shows the four brick types from your design sheet: brown, gray, green and black-gray-green, each in a long wall, a short wall, an arch, a corner and a battlement."}],"summary":"Wall, Gate, High Wall, Stairs"},{"id":"g-7-towers","cat":"guide","sec":"s7","secTitle":"7. Combat and Defenses","title":"Towers","pic":"b:gtower","blocks":[{"t":"cards","items":[{"pic":"b:gtower","n":"Tower","line":"Stage 1 · 120 wood","d":"Wooden tower: archers shoot from it, a knight guards its door."},{"pic":"b:stower","n":"Stone Tower","line":"Stage 3 · 20 wood, 60 stone","d":"Far tougher than the wooden tower; shoots farther, holds more archers."},{"pic":"b:lookout","n":"Lookout Tower","line":"Stage 2 · 40 wood, 50 stone","d":"Tall and slim: archers on top see and shoot very far."},{"pic":"b:roundtower","n":"Round Tower","line":"Stage 4 · 60 wood, 160 stone, 50 gold","d":"Giant tower that carries a ballista or a trebuchet."},{"pic":"b:greattower","n":"Great Tower","line":"Stage 4 · 40 wood, 120 stone, 30 gold","d":"The strongest tower; can carry a siege engine."}]},{"t":"ul","items":["Every lookout tower gets a sentry at the door, a longbowman and an archer at the top.","At stage 4 the giant towers come empty. You add a ballista (400 gold, 150 wood) or, at stage 5, a trebuchet (800 gold, 300 wood, 100 stone). (Build)","At stage 5 the towers still come empty: you buy each one’s engine. The rivals buy theirs by themselves. <span class=\"new fx\">CORRECTED</span>"]}],"summary":"Tower, Stone Tower, Lookout Tower, Round Tower, Great Tower"},{"id":"g-7-moats-and-spikes","cat":"guide","sec":"s7","secTitle":"7. Combat and Defenses","title":"Moats and spikes","pic":"b:gtower","blocks":[{"t":"cards","items":[{"pic":"b:moat","n":"Moat","line":"Stage 2 · free","d":"Water that stops people and engines; citizens, spearmen, swordsmen and flamethrowers can fill it."},{"pic":"b:pit","n":"Spike Pit","line":"Stage 1 · 10 wood","d":"Hidden spikes: one strike kills an enemy (knights, berserkers and mounted knights take two)."}]},{"t":"ul","items":["A moat is a severe movement barrier. It does not damage or kill.","Citizens, spearmen, swordsmen and flamethrowers can fill a moat in (your decision after Phase 4C). Knights, anyone on a horse, berserkers, archers and macemen cannot. (The list of fillers is one setting.) <span class=\"new fx\">CORRECTED</span>","Once a section is filled it becomes normal ground for good. Everyone, including enemies, can cross it.","Spikes are lethal: anyone who steps on them dies from one strike, except knights, berserkers and mounted knights, who take two (a mounted knight’s horse falls at the first). Rival lords and kings die from one strike too. <span class=\"new fx\">CORRECTED</span>","Units of the spike owner’s own faction are not hurt. The same rules cover mounted units, horses and bandits."]}],"summary":"Moat, Spike Pit"},{"id":"g-7-how-a-battle-plays","cat":"guide","sec":"s7","secTitle":"7. Combat and Defenses","title":"How a battle plays","pic":"b:gtower","blocks":[{"t":"ul","items":["Red and yellow sparks fly on every hit. There is no blood. You hear sword clashes and arrow sounds, and bricks fly and tumble through the air.","Wind, rain and snow change how far arrows fly.","Knights and the king take only a quarter of the damage from ordinary weapons. Knights, kings, ballistas and trebuchets hurt them fully.","Small groups are scouts and light raiders. Random rogues and bandits belong to no rival. They steal and run off.","Raiders follow their routes, cut through trees, and break walls with rams.","<b>Soldiers come back.</b> A soldier who goes after an enemy by himself turns back once he is about a dozen squares from where he started, so he is not drawn into a rival’s castle. Soldiers you send yourself go where you send them. <span class=\"new\">NEW</span>","<b>A war won.</b> When a raid is beaten off (at least 6 in 10 of the raiders fall and your keep stands), a Victory banner shows. So does defeating a rival. Each war won brings citizens sooner and cheaper for ten minutes (section 11). <span class=\"new\">NEW</span>"]}],"summary":"Red and yellow sparks fly on every hit. There is no blood. You hear sword clashes and arrow sounds, and…"},{"id":"g-7-patrol-guard-formations-and-rally-flags","cat":"guide","sec":"s7","secTitle":"7. Combat and Defenses","title":"Patrol, Guard, formations and rally flags","pic":"b:gtower","blocks":[{"t":"ul","items":["<b>Patrol:</b> press Patrol on the troop diamond, then draw a route with a mouse or finger. Selected soldiers follow it again and again until you change it or a fight interrupts it. <span class=\"new\">NEW</span>","<b>Guard:</b> press Guard on the diamond and tap a place: they defend that area.","<b>Formations:</b> choose a shape on the diamond and the group marches in it, at the pace of the slowest (section 5). <span class=\"new\">NEW</span>","<b>Rally flags:</b> a flag beside a shield for military, beside a person for citizens, beside a siege weapon for siege equipment. Soldiers and siege follow the main army’s destination unless you give them separate orders. Idle citizens return to the campfire.","<b>Escorted work groups (stage 3):</b> harvesting groups go out together with soldiers to protect them from bandits, wolves and bears. It is automatic. Clicking the building tells you which group needs a soldier, for example “group one needs a soldier”. Only basic soldiers escort: sword, spear or archer, never flamethrowers."]}],"summary":"Patrol: press Patrol on the troop diamond, then draw a route with a mouse or finger. Selected soldiers…"},{"id":"g-8-buildings-and-industries","cat":"guide","sec":"s8","secTitle":"8. Buildings and Industries","title":"Buildings and Industries","pic":"b:house","blocks":[{"t":"p","h":"<i>What each building does, what it costs, who works in it, and how it grows.</i>"},{"t":"p","h":"Click any building and a box opens whose background is a still picture of the inside of that building. The picture changes as the building grows. First, the big industries in depth, with photographs of their boxes. After them, every building at a glance with its cost."}],"summary":"What each building does, what it costs, who works in it, and how it grows."},{"id":"g-8-the-keep-and-the-shack","cat":"guide","sec":"s8","secTitle":"8. Buildings and Industries","title":"The keep and the shack","pic":"b:house","blocks":[{"t":"line","h":"From the start · your home"},{"t":"ul","items":["You start in a shack and the castle grows around it through five stages.","Your keep is the heart of the game. If it is destroyed, you lose.","Sick people are sent to the keep to be cared for."]}],"parent":"The big industries","summary":"From the start · your home"},{"id":"g-8-woodcutter-s-hut-and-the-wood-and-iron-y","cat":"guide","sec":"s8","secTitle":"8. Buildings and Industries","title":"Woodcutter’s hut and the wood and iron yard","pic":"b:woodhut","blocks":[{"t":"line","h":"Stage 1 · 30 wood · one building that grows"},{"t":"ul","items":["Woodcutters fell trees near it. Huts merge into bigger buildings, even when built in separate places.","Stage 1: up to 4 huts of 2 people. Stage 2: up to 3 yards of 5 people. (Build)","Stage 3: two buildings of 10 people each, and the blacksmith joins so iron work begins.","Stages 4 and 5: one big yard. At stage 5 it holds 15 on wood and 10 on iron, and you choose the split.","From stage 3 horse-drawn wagons carry the workers to the forest. Arrows and ballista bolts still cost wood."]}],"parent":"The big industries","summary":"Stage 1 · 30 wood · one building that grows"},{"id":"g-8-quarry-and-ox-cart","cat":"guide","sec":"s8","secTitle":"8. Buildings and Industries","title":"Quarry and ox cart","pic":"b:quarry","blocks":[{"t":"line","h":"Stage 2 · 40 wood · beside grey rocks"},{"t":"ul","items":["Grows and gets more sophisticated, then stops. Maximum two quarries, 10 people in each.","Workers go out in sets of two with oxen, and one person always stays behind.","On foot, a quarryman can only gather nearby stone. Far stone needs oxen. Going from one ox to two is automatic and free as you grow.","Stronger workers and oxen need more food and cost more to replace."]}],"parent":"The big industries","summary":"Stage 2 · 40 wood · beside grey rocks"},{"id":"g-8-the-field","cat":"guide","sec":"s8","secTitle":"8. Buildings and Industries","title":"The Field","pic":"b:wheatfarm","blocks":[{"t":"line","h":"Stage 1 · 40 wood"},{"t":"ul","items":["Up to 5 fields at every stage (they no longer merge), each holding up to 10 people. <span class=\"new fx\">CORRECTED</span>","Tap the field, anywhere on it: its box opens right beside it. + and − beside Wheat, Corn and Grapes put people on each crop or take them off. It can grow all three at once, in strips. A new field starts with two people on corn, so it feeds people at once.","Wheat grows fastest and goes to the mill (bread) and the alehouse. Corn is next and feeds your people straight from the granary. Grapes are the slowest, so they sell for the most, and the feast needs them.","Too much food? Take people off with −: they stay off and go back to gathering."]}],"parent":"The big industries","summary":"Stage 1 · 40 wood"},{"id":"g-8-the-farm-and-the-stable","cat":"guide","sec":"s8","secTitle":"8. Buildings and Industries","title":"The Farm and the stable","pic":"b:farm","blocks":[{"t":"line","h":"Farm 60 wood, stage 1 · stable 60 wood, stage 3"},{"t":"ul","items":["Up to 2 farms, each holding up to 5 people. Tap the farm (its box opens beside it): − and + beside People set how many work there, and you tick the animals it raises: chickens, cows, pigs and ducks (and turkeys and sheep, which the feast needs). You see them walking about the pen; only the ticked ones are born.","The keepers bring in eggs, milk and meat (food). Cows give leather, and their bull calves become oxen for the quarries.","The farm gets better with time: level 2 after 6 minutes of work, level 3 after 15 minutes with a stable beside it. Each level breeds faster and holds more.","The stable stands beside the farm and needs 4 people. Horses live there, pull wagons and turn knights into mounted knights."]}],"parent":"The big industries","summary":"Farm 60 wood, stage 1 · stable 60 wood, stage 3"},{"id":"g-8-guards-wells-and-lookouts","cat":"guide","sec":"s8","secTitle":"8. Buildings and Industries","title":"Guards, wells and lookouts","pic":"b:lookout","blocks":[{"t":"line","h":"Guards free · well 30 wood · lookout 40 wood"},{"t":"ul","items":["Fields and farms can stand far from the keep, so their guards <b>come with them</b>, free, as a tower comes with its knight: 2 with a field, 1 with a farm. Each has a knight’s strength, on foot, even before you can train knights, takes no place in your houses, and stays with his field. If one falls, <b>Reserve a guard</b> in the box brings a new one, free.","A <b>well</b> makes things grow 25% faster, and is water for putting out fires nearby.","A <b>lookout tower</b> sees the land around and rings the bell when raiders come near.","Happy people grow food faster (25% when very happy, 20% slower when upset)."]}],"parent":"The big industries","summary":"Guards free · well 30 wood · lookout 40 wood"},{"id":"g-8-mill-and-bakeries","cat":"guide","sec":"s8","secTitle":"8. Buildings and Industries","title":"Mill and bakeries","pic":"b:mill","blocks":[{"t":"line","h":"Mill stage 2, 60 wood (Build) · bakery stage 3, 50 wood"},{"t":"ul","items":["One mill feeds five bakeries, each holding up to 3 people. At stage 3 you build one mill and it comes with the five bakeries.","Before stage 3 only two mills can be built, with 2 people each.","Output is about enough bread for 20 people every couple of minutes. People eat bread fast. Cy Young bakes four and a half times as much.","Flour can be bought separately at the market only for cakes for the feast, or to sell."]}],"parent":"The big industries","summary":"Mill stage 2, 60 wood (Build) · bakery stage 3, 50 wood"},{"id":"g-8-granary-and-stockpile","cat":"guide","sec":"s8","secTitle":"8. Buildings and Industries","title":"Granary and stockpile","pic":"b:granary","blocks":[{"t":"line","h":"Granary 40 wood · stockpile 20 wood · stage 1"},{"t":"ul","items":["The granary holds 300 food, and 800 once expanded at stage 3. Fruit and all food go in automatically.","Too much food without expansion brings bugs, disease and deaths. Fix it by taking workers off food (they sit by the campfire, no penalty) or by selling food.","The stockpile keeps wood, stone, iron and goods closer to where they are gathered."]}],"parent":"The big industries","summary":"Granary 40 wood · stockpile 20 wood · stage 1"},{"id":"g-8-alehouse-tavern-and-brewery","cat":"guide","sec":"s8","secTitle":"8. Buildings and Industries","title":"Alehouse, tavern and brewery","pic":"b:alehouse","blocks":[{"t":"line","h":"Alehouse stage 1 · tavern and brewery stage 2"},{"t":"ul","items":["The alehouse needs one worker. People buy ale there and take it home. Set its price Cheap, Fair or Dear.","Too cheap and some people end up drunk and strange in the streets. Too expensive and they get angry. Find the middle price. Ale costs more in wartime.","The tavern serves more people and people rest there on breaks. The brewery brews ale from the hop farm’s hops."]}],"parent":"The big industries","summary":"Alehouse stage 1 · tavern and brewery stage 2"},{"id":"g-8-market","cat":"guide","sec":"s8","secTitle":"8. Buildings and Industries","title":"Market","pic":"b:market","blocks":[{"t":"line","h":"Stage 3 · 60 wood · one of the most valuable buildings"},{"t":"ul","items":["If it is destroyed it hurts the most. You can trade goods with rivals who are willing to trade.","Goods you buy cost 2.5 times what they cost to make, and you sell at 1.2 times. School level 2 changes that to 2 and 1.5, and level 3 to 1.8 and 1.6. (Build)","Your people’s mood also moves prices: up to 25 percent cheaper when they are happy and up to 40 percent higher when they are upset. Ticanologue pays half."]}],"parent":"The big industries","summary":"Stage 3 · 60 wood · one of the most valuable buildings"},{"id":"g-8-school-and-engineer-s-hut","cat":"guide","sec":"s8","secTitle":"8. Buildings and Industries","title":"School and engineer’s hut","pic":"b:school","blocks":[{"t":"line","h":"School stage 3 · engineer’s hut stage 3"},{"t":"ul","items":["The school starts small. Clicking it opens a menu to buy education. There are three levels covering better war and better building: less material lost, less money and fewer people needed to build, better trade.","The top level trains engineers and is needed before stage 5. It also holds the soldiers button (up to level 5).","The engineer’s hut houses four engineers who repair very fast and build and crew siege engines."]}],"parent":"The big industries","summary":"School stage 3 · engineer’s hut stage 3"},{"id":"g-8-apothecary-house-of-prayer-church-and-ab","cat":"guide","sec":"s8","secTitle":"8. Buildings and Industries","title":"Apothecary, house of prayer, church and abbey","pic":"b:chapel","blocks":[{"t":"line","h":"Healing and happiness"},{"t":"ul","items":["Once built, health and happiness are handled, unless the building is destroyed. Bigger ones are stronger: house of prayer (stage 2), church (stage 3), abbey (stage 4).","At stage 5 the apothecary offers a “make the doctor smarter” upgrade. After about two minutes the doctor heals faster.","Hekaranok’s abbeys are stronger still."]}],"parent":"The big industries","summary":"Healing and happiness"},{"id":"g-8-the-feast","cat":"guide","sec":"s8","secTitle":"8. Buildings and Industries","title":"The feast","pic":"b:house","blocks":[{"t":"line","h":"Stage 3 · never automatic"},{"t":"ul","items":["The old automatic feast is gone. You must gather grapes, apples, chickens, turkeys, a cow and a lamb or sheep.","It costs more than all your taxes for that session. In return people stay happy a long time, nothing makes them mad, and they work about twice as hard."]}],"parent":"The big industries","summary":"Stage 3 · never automatic"},{"id":"g-8-every-building-at-a-glance","cat":"guide","sec":"s8","secTitle":"8. Buildings and Industries","title":"Every building at a glance","pic":"b:house","blocks":[{"t":"h","h":"Homes, fields and farms"},{"t":"cards","items":[{"pic":"b:house","n":"House","line":"Stage 1 · 50 wood","d":"Room for your people; each house raises a new citizen every few minutes."},{"pic":"b:farm","n":"Farm","line":"Stage 1 · 60 wood","d":"Grows crops for food and keeps animals (cows, pigs, oxen, hens, turkeys, sheep)."},{"pic":"b:wheatfarm","n":"Field","line":"Stage 1 · 40 wood","d":"Grows wheat for the mill (flour, then bread) and for ale."},{"pic":"b:hopfarm","n":"Hop Farm","line":"Stage 2 · 40 wood","d":"Grows hops for the brewery’s ale."},{"pic":"b:vineyard","n":"Vineyard","line":"Stage 3 · 40 wood, 10 gold","d":"Grows grapes: food, and needed for a feast."},{"pic":"b:orchard","n":"Orchard","line":"Stage 3 · 40 wood, 10 gold","d":"Grows apples: food, and needed for a feast."},{"pic":"b:woodhut","n":"Woodcutter’s Hut","line":"Stage 1 · 30 wood","d":"Woodcutters fell trees near it; it grows into the wood and iron yard."},{"pic":"b:quarry","n":"Quarry","line":"Stage 2 · 40 wood","d":"Beside grey rocks: cuts stone; its ox cart hauls it home."},{"pic":"b:ironmine","n":"Iron Mine","line":"Stage 3 · 40 wood","d":"On the red iron ground: digs iron for weapons and crossbows."},{"pic":"b:stockpile","n":"Stockpile","line":"Stage 1 · 20 wood","d":"A store for wood, stone, iron and goods, closer to where they are gathered."}]},{"t":"h","h":"Food and drink"},{"t":"cards","items":[{"pic":"b:granary","n":"Granary","line":"Stage 1 · 40 wood","d":"Stores food (300, 800 once expanded). Beyond that, bugs spoil the extra."},{"pic":"b:mill","n":"Mill","line":"Stage 2 · 60 wood","d":"Grinds wheat into flour for the bakeries."},{"pic":"b:bakery","n":"Bakery","line":"Stage 3 · 50 wood","d":"Bakes bread from flour (Cy Young bakes four and a half times as much)."},{"pic":"b:brewery","n":"Brewery","line":"Stage 2 · 50 wood","d":"Brews ale from hops."},{"pic":"b:alehouse","n":"Alehouse","line":"Stage 1 · 30 wood","d":"Serves ale to cheer your people; set its price Cheap, Fair or Dear."},{"pic":"b:tavern","n":"Tavern","line":"Stage 2 · 60 wood","d":"Serves ale to more people than an alehouse; people rest here on breaks."}]},{"t":"h","h":"Care, happiness and rule"},{"t":"cards","items":[{"pic":"b:chapel","n":"House of Prayer","line":"Stage 2 · 80 wood, 40 gold","d":"Lifts spirits and heals the sick nearby."},{"pic":"b:church","n":"Church","line":"Stage 3 · 80 wood, 80 stone, 60 gold","d":"A bigger house of prayer: cheers and heals more people."},{"pic":"b:abbey","n":"Abbey","line":"Stage 4 · 100 wood, 160 stone, 120 gold","d":"The greatest house of prayer and healing (stronger for Hekaranok)."},{"pic":"b:apothecary","n":"Apothecary","line":"Stage 2 · 50 wood, 20 gold","d":"Heals the sick nearby and cheers a few people."},{"pic":"b:garden","n":"Garden","line":"Stage 1 · 20 wood, 10 gold","d":"Cheers people (they work a little slower)."},{"pic":"b:stocks","n":"Stocks","line":"Stage 2 · 15 wood","d":"Frighten people into working harder (they are less happy)."}]},{"t":"h","h":"Trade, learning and war workshops"},{"t":"cards","items":[{"pic":"b:market","n":"Market","line":"Stage 3 · 60 wood","d":"Buy and sell goods and weapons for gold (Ticanologue pays half)."},{"pic":"b:school","n":"School","line":"Stage 3 · 80 wood, 40 stone, 60 gold","d":"Lessons: less waste, cheaper and quicker building, better trade, trained soldiers, engineers."},{"pic":"b:engineerhut","n":"Engineer’s Hut","line":"Stage 3 · 50 wood, 20 stone","d":"Houses four engineers who build and crew siege engines."},{"pic":"b:stable","n":"Stable","line":"Stage 3 · 60 wood","d":"Raises horses that turn knights into mounted knights."},{"pic":"b:bowyer","n":"Fletcher (Bowyer)","line":"Stage 1 · 40 wood","d":"Makes bows from wood."},{"pic":"b:poleturner","n":"Spear-maker","line":"Stage 1 · 40 wood","d":"Makes spears from wood."},{"pic":"b:smithy","n":"Blacksmith","line":"Stage 3 · 50 wood","d":"Makes swords, maces or knight armour from iron."},{"pic":"b:armory","n":"Armory","line":"Stage 1 · 50 wood","d":"Stores weapons; soldiers are armed from it."},{"pic":"b:waterpot","n":"Water Pot","line":"Stage 1 · 10 wood","d":"Water for putting out fires; it grows as time passes."}]},{"t":"p","h":"Costs are read from the game today. The keep has no cost; its picture is a photograph from the game <span class=\"new\">NEW</span>."}],"summary":"House, Farm, Field, Hop Farm, Vineyard, Orchard, Woodcutter’s Hut, Quarry, Iron Mine, Stockpile"},{"id":"g-9-goods-weapons-and-how-soldiers-are-made","cat":"guide","sec":"s9","secTitle":"9. Goods, Weapons and How Soldiers Are Made","title":"Goods, Weapons and How Soldiers Are Made","pic":"w:sword","blocks":[{"t":"p","h":"<i>Every item your people make, move and spend, and where each one goes.</i>"}],"summary":"Every item your people make, move and spend, and where each one goes."},{"id":"g-9-goods","cat":"guide","sec":"s9","secTitle":"9. Goods, Weapons and How Soldiers Are Made","title":"Goods","pic":"w:sword","blocks":[{"t":"cards","items":[{"pic":"r:food","n":"Food","line":"","d":"Crops, berries, corn, eggs, milk, meat and bread: everyone eats."},{"pic":"r:wood","n":"Wood","line":"","d":"For building, bows and spears."},{"pic":"r:stone","n":"Stone","line":"","d":"For stone walls, towers and growing the castle."},{"pic":"","n":"Iron","line":"","d":"For swords, maces, armour and crossbows."},{"pic":"r:gold","n":"Gold","line":"","d":"From taxes and trade; pays wages, training and calling citizens."},{"pic":"","n":"Wheat","line":"","d":"Ground into flour; brewed into ale."},{"pic":"","n":"Flour","line":"","d":"Baked into bread."},{"pic":"","n":"Bread","line":"","d":"Good food that adds variety."},{"pic":"","n":"Hops","line":"","d":"Brewed into ale."},{"pic":"","n":"Ale","line":"","d":"Served at the alehouse and tavern to cheer people."},{"pic":"","n":"Grapes","line":"","d":"From the field (slowest crop); worth the most of the crops; part of a feast."},{"pic":"","n":"Apples","line":"","d":"Food, and part of a feast."},{"pic":"","n":"Leather","line":"","d":"From the farm’s animals; berserkers need it."}]}],"summary":"Food, Wood, Stone, Iron, Gold, Wheat, Flour, Bread, Hops, Ale, Grapes, Apples, Leather"},{"id":"g-9-weapons","cat":"guide","sec":"s9","secTitle":"9. Goods, Weapons and How Soldiers Are Made","title":"Weapons","pic":"w:sword","blocks":[{"t":"cards","items":[{"pic":"w:sword","n":"Sword","line":"","d":"For swordsmen, knights and flamethrowers."},{"pic":"w:spear","n":"Spear","line":"","d":"For spearmen."},{"pic":"","n":"Bow","line":"","d":"For archers, longbowmen and crossbowmen."},{"pic":"","n":"Mace","line":"","d":"For macemen and berserkers."},{"pic":"","n":"Knight Armour","line":"","d":"For knights and flamethrowers."}]}],"summary":"Sword, Spear, Bow, Mace, Knight Armour"},{"id":"g-9-how-a-soldier-is-made","cat":"guide","sec":"s9","secTitle":"9. Goods, Weapons and How Soldiers Are Made","title":"How a soldier is made","pic":"w:sword","blocks":[{"t":"p","h":"Weapons come from workshops, wait in the armory, and are issued to a new soldier together with gold."},{"t":"table","head":["Soldier","Workshop","Needs","Stage"],"rows":[["Spearman","Spear-maker","1 spear + 10 gold","1"],["Archer","Fletcher","1 bow + 10 gold","1"],["Longbowman","Fletcher","1 bow + 15 gold","2"],["Crossbowman","Fletcher + iron mine","1 bow + 2 iron + 15 gold","3"],["Swordsman","Blacksmith","1 sword + 10 gold","3"],["Maceman","Blacksmith","1 mace + 10 gold","3"],["Berserker (every faction)","Blacksmith + farm","1 mace + 2 leather + 10 gold","3"],["Knight","Blacksmith","1 sword + armour + 20 gold","3"],["Mounted knight","Knight + stable","A knight plus a horse","4"],["Flamethrower squad","Blacksmith","Sword, armour and 20 gold","4"],["Citizen <span class=\"new\">NEW</span>","The Citizen button (Town list)","About 20 food + 10 gold, more when unhappy (section 11)","1"]]}],"summary":"Weapons come from workshops, wait in the armory, and are issued to a new soldier together with gold."},{"id":"g-10-economy-mood-and-trade","cat":"guide","sec":"s10","secTitle":"10. Economy, Mood and Trade","title":"Economy, Mood and Trade","pic":"i:coins","blocks":[{"t":"p","h":"<i>How goods move, how people feel, and how money works.</i>"}],"summary":"How goods move, how people feel, and how money works."},{"id":"g-10-the-chains-that-make-things","cat":"guide","sec":"s10","secTitle":"10. Economy, Mood and Trade","title":"The chains that make things","pic":"i:coins","blocks":[{"t":"p","h":"<b>Bread</b> → Field (wheat) → Mill → 5 bakeries → People eat"},{"t":"p","h":"<b>Corn</b> → Field (corn) → Granary → People eat"},{"t":"p","h":"<b>Eggs, milk, meat</b> → Farm (animals) → Granary → People eat"},{"t":"p","h":"<b>Animals</b> → Farm → Market → Top price, always"},{"t":"p","h":"<b>Ale</b> → Hop farm → Brewery → Alehouse / tavern → People buy ale"},{"t":"p","h":"<b>Stone</b> → Quarry (+ oxen) → Stockpile → Walls, buildings, growing the castle"},{"t":"p","h":"<b>Wood and iron</b> → Wood yard / iron mine → Fletcher, spear-maker, smith → Bows, spears, swords, maces, armour"},{"t":"p","h":"<b>Money</b> → Taxes, surplus food and goods → Market → Gold → Soldiers, upgrades, citizens"}],"summary":"Bread → Field (wheat) → Mill → 5 bakeries → People eat"},{"id":"g-10-what-keeps-people-happy","cat":"guide","sec":"s10","secTitle":"10. Economy, Mood and Trade","title":"What keeps people happy","pic":"i:coins","blocks":[{"t":"ul","items":["Rations, taxes, ale, a House of Prayer, a variety of food, not too much crowding, and no sickness.","Unhappy people leave. Happy towns attract settlers.","People who eat well get fat, which makes them happier but slower.","Sick people are sent to the keep to be cared for.","<b>Mourning:</b> when your people or soldiers are killed, the town mourns for two minutes. The mood box lists it as a reason, and it passes by itself. <span class=\"new\">NEW</span>","<b>Happiness and new citizens:</b> the happier your people, the sooner and cheaper a called citizen comes (section 11). <span class=\"new\">NEW</span>"]}],"summary":"Rations, taxes, ale, a House of Prayer, a variety of food, not too much crowding, and no sickness."},{"id":"g-10-taxes","cat":"guide","sec":"s10","secTitle":"10. Economy, Mood and Trade","title":"Taxes","pic":"i:coins","blocks":[{"t":"p","h":"Raise or lower taxes with a simple control. Higher taxes bring in more gold and make people less happy. Lower taxes make them happier and bring in less. A person’s detail box shows what he makes and what he pays."}],"summary":"Raise or lower taxes with a simple control. Higher taxes bring in more gold and make people less happy.…"},{"id":"g-10-trade","cat":"guide","sec":"s10","secTitle":"10. Economy, Mood and Trade","title":"Trade","pic":"i:coins","blocks":[{"t":"ul","items":["The market buys and sells everything. Buying always costs more than making it yourself.","One friendly rival can be a trading friend who trades with you at the same stage level.","Cy Young sells its surplus food. Ticanologue pays half price at the market."]}],"summary":"The market buys and sells everything. Buying always costs more than making it yourself."},{"id":"g-11-citizens-and-how-you-read-them","cat":"guide","sec":"s11","secTitle":"11. Citizens and How You Read Them","title":"Citizens and How You Read Them","pic":"u:civ","blocks":[{"t":"p","h":"<i>Every person can tell you what they are doing and what they need.</i>"},{"t":"ul","items":["Citizens stay near the castle and do not wander outside it.","When citizens are killed they must be replaced. This is the main caveat of the game. New citizens come in and work automatically.","A building needs only one citizen to run. A second citizen takes about 3 to 5 minutes to grow in a house. Some may still be in school, and that is shown.","You can also <b>call</b> a citizen from the countryside, for food and gold (below). <span class=\"new\">NEW</span>"]}],"summary":"Every person can tell you what they are doing and what they need."},{"id":"g-11-calling-more-citizens","cat":"guide","sec":"s11","secTitle":"11. Citizens and How You Read Them","title":"Calling more citizens","pic":"u:civ","blocks":[{"t":"p","h":"Open the <b>Town</b> list (key 1) and find the <b>Citizen</b> button (a citizen’s picture). Touch it, or rest the mouse on it, and its label shows what calling one costs right now and how long he takes, for example “20 food · 10 gold · 1:00”. Tap it to call him: you pay, a banner says when he will arrive, and when his wait is over he walks in along the road, saying he answers your call. Your houses go on raising their own children as before. (Your Phase 4F request.)"}],"summary":"Open the Town list (key 1) and find the Citizen button (a citizen’s picture). Touch it, or rest the mouse…"},{"id":"g-11-what-changes-the-cost-and-the-wait","cat":"guide","sec":"s11","secTitle":"11. Citizens and How You Read Them","title":"What changes the cost and the wait","pic":"u:civ","blocks":[{"t":"table","head":["","The rule"],"rows":[["<b>Happiness</b>","The unhappier your people, the longer word takes to spread and the more a citizen costs. Below 20 happiness it takes about four and a half minutes. Happy people (70 or more): sooner and cheaper than the normal price."],["<b>Wars won</b>","A raid beaten off (at least 6 in 10 of its raiders fall and your keep stands) or a rival defeated. Each war won counts for 10 minutes, and up to 3 count at once. Each makes the wait and the cost about 15% less, and makes the houses raise their children sooner."],["<b>Generals</b>","Soldiers with 7 or more veteran stars (five-star generals too), in the field or in the camp. Up to 3 count. Each makes the wait about 10% shorter and the cost 5% less, and makes the houses raise their children sooner."],["<b>Limits</b>","Your houses must have room for him. At most 5 can be on their way at once. However much the wars and generals help, the wait is never shorter than 15 seconds."]]}],"summary":"Happiness, Wars won, Generals…"},{"id":"g-11-the-numbers-today-build","cat":"guide","sec":"s11","secTitle":"11. Citizens and How You Read Them","title":"The numbers today (Build)","pic":"u:civ","blocks":[{"t":"p","h":"Happiness alone, with no wars won and no generals:"},{"t":"table","head":["Happiness","Food","Gold","Wait"],"rows":[["90","17","9","0:45"],["75","17","9","0:45"],["60","20","10","1:00"],["45","25","13","1:36"],["30","32","16","2:30"],["15","44","22","4:30"]]},{"t":"p","h":"At happiness 60, with wars won (generals work the same way, a little more gently):"},{"t":"table","head":["Wars won","Food","Gold","Wait","Houses raise children"],"rows":[["0","20","10","1:00","as usual"],["1","17","9","0:51","1.18 times as fast"],["2","14","7","0:43","1.38 times as fast"],["3","12","6","0:37","1.63 times as fast"]]},{"t":"p","h":"<b>The balancing act.</b> An unhappy town that keeps losing gets fewer new people, slowly and at a high price. A town that wins its wars and keeps its veterans alive gets them quickly and cheaply, even when it is not very happy. All these numbers are one block in the game’s settings (CITIZEN_CALL), so they can be tuned."}],"summary":"Happiness alone, with no wars won and no generals:"},{"id":"g-11-tap-and-hold","cat":"guide","sec":"s11","secTitle":"11. Citizens and How You Read Them","title":"Tap and hold","pic":"u:civ","blocks":[{"t":"table","head":["Quick tap","Press and hold"],"rows":[["A small picture of the job (a pick for the quarry). Soldiers show stars, level and education. No words.","1 to 2 seconds. The person speaks what they do or need, and a detail box opens."]]},{"t":"ul","items":["On an iPad or large screen the detail box floats small next to the person and slides over at screen edges. On a phone it slides up along the bottom.","The detail box shows whether the person is happy and, if not, why, their education level once the school is built, their job, any concerns such as taxes, how much they make, and how much tax they pay.","Only the held person speaks, one at a time, so nothing talks by accident."]}],"summary":"A small picture of the job (a pick for the quarry). Soldiers show stars, level and education. No words.…"},{"id":"g-11-the-people-tab","cat":"guide","sec":"s11","secTitle":"11. Citizens and How You Read Them","title":"The People tab","pic":"u:civ","blocks":[{"t":"p","h":"The face on the corner of the troop diamond, at the bottom left, is always available <span class=\"new fx\">CORRECTED</span>. It opens a well laid-out, scrollable panel that pauses the game. It shows how many people are growing, how many there are, their jobs, and the same information you get from holding on one person."}],"summary":"The face on the corner of the troop diamond, at the bottom left, is always available CORRECTED . It opens…"},{"id":"g-11-needs-alerts","cat":"guide","sec":"s11","secTitle":"11. Citizens and How You Read Them","title":"Needs alerts","pic":"u:civ","blocks":[{"t":"ul","items":["Every person and every industry says what is needed, for example “Oxen needed, my lord.” or “I need better education, my lord.”","It is spoken with the device’s own built-in speech and also shown as text. The Art of War advisor shares the same voice.","Only the single most urgent need is spoken at a time. No sound files are used."]}],"summary":"Every person and every industry says what is needed, for example “Oxen needed, my lord.” or “I need better…"},{"id":"g-12-fire-and-repair","cat":"guide","sec":"s12","secTitle":"12. Fire and Repair","title":"Fire and Repair","pic":"i:fire","blocks":[{"t":"p","h":"<i>Fires are fought and broken buildings mend themselves.</i>"}],"summary":"Fires are fought and broken buildings mend themselves."},{"id":"g-12-fire","cat":"guide","sec":"s12","secTitle":"12. Fire and Repair","title":"Fire","pic":"i:fire","blocks":[{"t":"p","h":"Fire seen → Alarm rings → Citizens fetch water → Fire out"},{"t":"ul","items":["When a fire is seen, an alarm rings in the castle and citizens automatically fetch water and put it out.","Each area has a water pot manned by one person. The pot grows over time.","Citizens put out fires faster as the school educates them, including bigger fires.","If a fire burns about ten seconds with no one addressing it, half the building burns down and needs repair.","Fire always moves like real fire."]}],"summary":"Fire seen → Alarm rings → Citizens fetch water → Fire out"},{"id":"g-12-repair","cat":"guide","sec":"s12","secTitle":"12. Fire and Repair","title":"Repair","pic":"i:fire","blocks":[{"t":"ul","items":["Damaged or destroyed buildings repair automatically, with no click. The people who worked there repair them if alive, otherwise other citizens come out.","Engineers repair very fast. Regular citizens take twice as long. Better education means faster repair.","Rebuilding a destroyed building takes twice as long as the original build.","If supplies run out, repair waits until supplies return. This applies to every building, every time."]}],"summary":"Damaged or destroyed buildings repair automatically, with no click. The people who worked there repair…"},{"id":"g-13-the-world-the-map-and-the-table","cat":"guide","sec":"s13","secTitle":"13. The World, the Map and the Table","title":"The World, the Map and the Table","pic":"i:map","blocks":[{"t":"p","h":"<i>Fog of war, random starts, the views, the table, the glass, the water and the wildlife.</i>"}],"summary":"Fog of war, random starts, the views, the table, the glass, the water and the wildlife."},{"id":"g-13-fog-of-war-and-random-starts","cat":"guide","sec":"s13","secTitle":"13. The World, the Map and the Table","title":"Fog of war and random starts","pic":"i:map","blocks":[{"t":"table","head":["","What it means"],"rows":[["<b>Unexplored</b>","Black. You know nothing here."],["<b>Explored</b>","Dim. You have been here; it stays revealed."],["<b>In sight</b>","Bright. Your units can see it now."]]},{"t":"ul","items":["There is fog of war in every game. You do not know where the enemy camps are. Explored ground stays revealed. More is revealed when you search or when an enemy shows itself.","Longbowmen see twice as far as other units. A ballista on a tower matches that. Berserkers see as far as a longbowman. All Psychana units see that far.","Your start position and each rival’s start position are different every game."]}],"summary":"Unexplored, Explored, In sight…"},{"id":"g-13-the-3d-view-and-the-flat-view","cat":"guide","sec":"s13","secTitle":"13. The World, the Map and the Table","title":"The 3D view and the flat view","pic":"i:map","blocks":[{"t":"p","h":"The game is 3D. The V key, or the view button in Settings, switches to a flat view, seen straight from above, and back. Everything works the same in both."}],"summary":"The game is 3D. The V key, or the view button in Settings, switches to a flat view, seen straight from…"},{"id":"g-13-the-battlefield","cat":"guide","sec":"s13","secTitle":"13. The World, the Map and the Table","title":"The battlefield","pic":"i:map","blocks":[{"t":"p","h":"These scenes are from your design sheet: a river valley with a stone bridge, a mountain pass, and a castle approach."}],"summary":"These scenes are from your design sheet: a river valley with a stone bridge, a mountain pass, and a castle…"},{"id":"g-13-the-table-the-bar-and-the-glass","cat":"guide","sec":"s13","secTitle":"13. The World, the Map and the Table","title":"The table, the bar and the glass","pic":"i:map","blocks":[{"t":"ul","items":["The board sits on a rich brown wood table with a polished finish and visible grain.","A brass and gold bar frames the playfield. Inside it, from the land outward: a band of moving water, then the bar. Where the bar meets the table the wood steps like crown molding.","Each corner has a round gold ball with a land on it: <b>Russia top left, the United States top right, Australia bottom left, South America bottom right</b>. <span class=\"new fx\">CORRECTED</span> (The layout is one setting.)","Beyond the bar is dark glass that reflects the table and the live game. The closer you scroll to the edge, the more glass you see. The reflection fades if the game slows down."]}],"summary":"The board sits on a rich brown wood table with a polished finish and visible grain."},{"id":"g-13-water-and-wildlife","cat":"guide","sec":"s13","secTitle":"13. The World, the Map and the Table","title":"Water and wildlife","pic":"i:map","blocks":[{"t":"ul","items":["Water moves with gentle waves and occasional splashes.","Now and then a fish jumps. Birds fly over. Butterflies and frogs appear near the shore.","All of it is sporadic and light, with a cap on how many appear at once."]}],"summary":"Water moves with gentle waves and occasional splashes."},{"id":"g-14-rivals-trade-and-winning","cat":"guide","sec":"s14","secTitle":"14. Rivals, Trade and Winning","title":"Rivals, Trade and Winning","pic":"i:raid","blocks":[{"t":"p","h":"<i>The computer plays the same four factions by the same rules.</i>"},{"t":"ul","items":["Every rival plays one of the four factions. Each rival gets a different faction when possible, and its name and colors show in the game.","Rivals follow the same five stages and economy as you. They start small with a shack and build up over time. They never start with a finished castle.","A rival’s stage depends on its economy. Raiding its farms and food slows it. A rival rushed early is small and can fall fast, so a game can end in about 15 minutes.","Whoever reaches stage 5 first is very hard to kill, so slowing a rival’s growth matters.","Rogues and bandits belong to no rival. They steal and run off.","One rival can be a trading friend. The others are enemies.","The game is meant to be challenging but winnable. Difficulty tunes how fast the rivals grow.","Each raid you beat off, and each rival you defeat, is a <b>war won</b>, with a Victory banner. Wars won bring citizens sooner and cheaper (section 11). <span class=\"new\">NEW</span>"]}],"summary":"The computer plays the same four factions by the same rules."},{"id":"g-14-what-a-rival-needs-to-grow","cat":"guide","sec":"s14","secTitle":"14. Rivals, Trade and Winning","title":"What a rival needs to grow","pic":"i:raid","blocks":[{"t":"p","h":"The rivals grow by their own table, the same on every difficulty (their difficulty is how fast they work). When your own stage numbers were lowered in Phase 4D, the rivals kept theirs, so lowering yours did not make their raids stronger sooner. (Build)"},{"t":"table","head":["Stage","People","Food","Stone","Iron"],"rows":[["<b>2. Homestead</b>","12","150","—","—"],["<b>3. Hold</b>","22","300","150","—"],["<b>4. Castle</b>","35","500","300","80"],["<b>5. Stronghold</b>","50","800","500","200"]]}],"summary":"The rivals grow by their own table, the same on every difficulty (their difficulty is how fast they work).…"},{"id":"g-14-when-the-raids-come","cat":"guide","sec":"s14","secTitle":"14. Rivals, Trade and Winning","title":"When the raids come","pic":"i:raid","blocks":[{"t":"table","head":["Difficulty","Peace before the first raid","First bandits"],"rows":[["Easy","10 minutes","10 minutes"],["Medium","10 minutes","10 minutes"],["Hard","5 minutes","5 minutes"]]},{"t":"p","h":"After the first, each enemy rival’s first raid comes about a minute and a quarter after the one before. The trading friend never raids."}],"summary":"Easy, Medium, Hard…"},{"id":"g-14-how-strong-the-raids-are","cat":"guide","sec":"s14","secTitle":"14. Rivals, Trade and Winning","title":"How strong the raids are","pic":"i:raid","blocks":[{"t":"p","h":"Your decision after version 3: the Medium raids much stronger than the Easy ones, and the Hard raids the strongest. Two things make them so: how many soldiers a rival may keep (so how many it can send), and how hard each raider hits and how many blows he can take."},{"t":"table","head":["Difficulty","Army a rival may keep (stages 1 to 5)","Each raider"],"rows":[["<b>Easy</b>","2, 5, 8, 11, 14","as trained"],["<b>Medium</b>","4, 8, 14, 20, 25","hits 1.25 times as hard and takes 1.25 times the blows"],["<b>Hard</b>","6, 11, 19, 27, 34","hits 1.5 times as hard and takes 1.5 times the blows"]]},{"t":"p","h":"A rival keeps two of its soldiers at home and sends the rest. Raids also come more often on harder levels (about every 5, 4 and 3 minutes)."}],"summary":"Your decision after version 3: the Medium raids much stronger than the Easy ones, and the Hard raids the…"},{"id":"g-14-each-faction-s-weakness","cat":"guide","sec":"s14","secTitle":"14. Rivals, Trade and Winning","title":"Each faction’s weakness","pic":"i:raid","blocks":[{"t":"table","head":["Faction","Exploit it by"],"rows":[["Cy Young","Raiding farms and food early, before the money snowballs."],["Ticanologue","Destroying the market they paid so much to build."],["Hekaranok","Killing units outright. A killed unit cannot be healed."],["Psychana","Ringing your castle with towers that spot their sneaking units."]]}],"summary":"Cy Young, Ticanologue, Hekaranok…"},{"id":"g-15-advisor-hints-help-settings-and-saving","cat":"guide","sec":"s15","secTitle":"15. Advisor, Hints, Help, Settings and Saving","title":"Advisor, Hints, Help, Settings and Saving","pic":"i:gear","blocks":[{"t":"p","h":"<i>Help while you play, and your game kept safe.</i>"}],"summary":"Help while you play, and your game kept safe."},{"id":"g-15-the-art-of-war-advisor-and-hints","cat":"guide","sec":"s15","secTitle":"15. Advisor, Hints, Help, Settings and Saving","title":"The Art of War advisor and hints","pic":"i:gear","blocks":[{"t":"ul","items":["Always on. It cannot be turned off, even for experienced players.","A clear panel in a top corner that does not cover play.","Timely tips in the spirit of Sun Tzu’s <i>The Art of War</i>: take the high ground, set a trap, build a tower here, and where raiders are coming from.","Short gameplay hints share the same panel and the same voice, one at a time. They are compact and unobtrusive, especially on phones.","One tap puts a tip or a hint away. The next one comes later. <span class=\"new\">NEW</span>"]}],"summary":"Always on. It cannot be turned off, even for experienced players."},{"id":"g-15-the-help-screen","cat":"guide","sec":"s15","secTitle":"15. Advisor, Hints, Help, Settings and Saving","title":"The Help screen","pic":"i:gear","blocks":[{"t":"p","h":"Tap the <b>?</b> at the top (or press H) and Help opens with a <b>search box</b> and a <b>Topics</b> drop-down that lists every category. <span class=\"new\">NEW</span> On a computer the search box is ready to type in straight away."},{"t":"ul","items":["<b>Search:</b> type what you need in plain words (“how do I get stone?”). The answers appear as you type: first the short Help articles, then the matching parts of this guide, under “In the Master Guide”. Spelling slips are forgiven.","<b>Topics:</b> pick a category from the drop-down (or from the cards below it). <b>The Master Guide</b> is one of them: all of this guide, section by section, inside the game.","There are 96 short articles, each with a picture, plus the whole of this guide. (The “What is this?” button the boxes used to carry was taken off at your word.) <span class=\"new\">NEW</span>","Reading Help pauses the game (unless enemies are close). A double tap on Help’s text, the X, or Esc closes it."]}],"summary":"Tap the ? at the top (or press H) and Help opens with a search box and a Topics drop-down that lists every…"},{"id":"g-15-settings","cat":"guide","sec":"s15","secTitle":"15. Advisor, Hints, Help, Settings and Saving","title":"Settings","pic":"i:gear","blocks":[{"t":"ul","items":["The settings icon (a gear) replaces the word “Menu”. The question mark opens Help. Quit Game is inside Settings.","Music starts at a low volume with sliders for music and effects. Voice, weather, outlines, trees (detailed or simple) and the view (3D or flat) are switched here.","The Fix button is no longer in Settings or over people. A stuck building is mended from its own box (Remove &amp; rebuild). <span class=\"new fx\">CORRECTED</span>"]}],"summary":"The settings icon (a gear) replaces the word “Menu”. The question mark opens Help. Quit Game is inside…"},{"id":"g-15-saving-your-game","cat":"guide","sec":"s15","secTitle":"15. Advisor, Hints, Help, Settings and Saving","title":"Saving your game","pic":"i:gear","blocks":[{"t":"ul","items":["You can name each save, keep several, see a list with the name and the date and time, load one, or delete one. There is also an automatic save every few minutes.","You can also keep a save as a <b>file</b> on your device and load it again later, even on another device. The front page has a button to load a saved game. <span class=\"new\">NEW</span>","A save keeps everything: the map and fog of war, your faction and every rival, buildings and how they have grown, every person and soldier, stars and education, resources, your castle stage, patrols and rally flags, filled moats, spikes, and fires and repairs in progress.","It also keeps the wars you have won lately, the raids under way, formations and the town’s mourning. <span class=\"new\">NEW</span>","Save and Load are inside Settings."]}],"summary":"You can name each save, keep several, see a list with the name and the date and time, load one, or delete…"},{"id":"g-16-glossary-and-search-words","cat":"guide","sec":"s16","secTitle":"16. Glossary and Search Words","title":"Glossary and Search Words","pic":"i:book","blocks":[{"t":"p","h":"<i>The same words the in-game Help search will understand.</i>"},{"t":"table","head":["Word","Meaning","Word","Meaning"],"rows":[["<b>Abbey</b>","Healing and happiness building. Stronger for Hekaranok.","<b>Keep</b>","Your heart. Lose it and you lose."],["<b>Alehouse</b>","One worker. Sells ale. Stage 1.","<b>Knight</b>","Foot at stage 3, mounted at stage 4."],["<b>Archer</b>","Ranged soldier. Stage 1.","<b>Longbowman</b>","Twice the sight. Stage 2."],["<b>Ballista</b>","Bolt thrower. Stage 3. On towers, sees as far as a longbowman.","<b>Market</b>","Trade. Stage 3."],["<b>Bakery</b>","Five per mill, 3 people each.","<b>Mill</b>","Feeds five bakeries."],["<b>Bell</b>","Recalls Hekaranok’s healing units.","<b>Moat</b>","Barrier. Citizens, spearmen, swordsmen, flamethrowers fill it; it becomes ground."],["<b>Berserker</b>","Wild fighter. Stage 3. Every faction.","<b>Mourning <span class=\"new\">NEW</span></b>","Two minutes of sorrow after deaths."],["<b>Campfire</b>","Where idle citizens go.","<b>Patrol</b>","Draw a route soldiers repeat."],["<b>Catapult</b>","Siege stone thrower. Stage 4.","<b>Peace time <span class=\"new\">NEW</span></b>","10 minutes (5 on Hard) before the first raid."],["<b>Citizen button <span class=\"new\">NEW</span></b>","Town list. Calls one more citizen for food and gold.","<b>People tab</b>","The face on the diamond. All people at a glance."],["<b>Citizens</b>","Your workers. Replace them when killed.","<b>Quarry</b>","Stone. Stage 2. Max two."],["<b>Crossbowman</b>","Ranged. Stage 3.","<b>Rally flag</b>","Where new units gather."],["<b>Diamond <span class=\"new\">NEW</span></b>","The troop controls, bottom left.","<b>Repair</b>","Automatic. Rebuild takes twice as long."],["<b>Education</b>","School upgrades for people and soldiers.","<b>Save</b>","Named saves in Settings."],["<b>Engineer</b>","Fast repair; builds trebuchets.","<b>School</b>","Education. Stage 3."],["<b>Escort</b>","Soldiers who protect work groups.","<b>Spikes</b>","Lethal to enemies."],["<b>Export <span class=\"new\">NEW</span></b>","Keep a saved game as a file.","<b>Stable</b>","Horses and oxen. Stage 3."],["<b>Feast</b>","Costly, never automatic. Stage 3.","<b>Stage</b>","One of five castle levels."],["<b>Fire</b>","Citizens fetch water; 10 seconds burns half.","<b>Star</b>","Veteran mark. Each makes him stronger."],["<b>Flamethrower</b>","Squad of 10. Stage 4. Attack only.","<b>Tavern</b>","Stage 2. People rest here."],["<b>Flat view <span class=\"new\">NEW</span></b>","Seen from straight above. Key V.","<b>Taxes</b>","More gold, less happiness."],["<b>Fog of war</b>","Unexplored ground is hidden.","<b>Trebuchet</b>","Stage 5 siege."],["<b>Formation <span class=\"new\">NEW</span></b>","The shape a group marches in.","<b>Trophy</b>","Shows what the next stage needs."],["<b>Gate</b>","Intentional opening in a wall.","<b>Victory <span class=\"new\">NEW</span></b>","The banner for a war won."],["<b>General <span class=\"new\">NEW</span></b>","A soldier with 7 or more stars; five-star at 10.","<b>War won <span class=\"new\">NEW</span></b>","A raid beaten off, or a rival defeated."],["<b>Granary</b>","Stores food. Expands at stage 3.","<b>Wheat field</b>","Up to 10 workers."],["<b>Guard</b>","Command: defend an area.","<b>Wood yard</b>","Wood and iron building."],["<b>Help (?)</b>","Search keywords or activities.","",""]]}],"summary":"The same words the in-game Help search will understand."},{"id":"g-17-still-open","cat":"guide","sec":"s17","secTitle":"17. Still Open","title":"Still Open","pic":"i:book","blocks":[{"t":"p","h":"<i>Things still waiting on you, and things still being finished.</i>"}],"summary":"Things still waiting on you, and things still being finished."},{"id":"g-17-waiting-on-your-decision","cat":"guide","sec":"s17","secTitle":"17. Still Open","title":"Waiting on your decision","pic":"i:book","blocks":[{"t":"table","head":["Item","What the game does now","Your call"],"rows":[["The five-star general <span class=\"new\">NEW</span>","7 stars: a general. 10 stars: a five-star general (Claude’s reading of your answer). Both count the same toward calling citizens.","Is that right? Should a five-star general count for more?"],["Raid strength: the numbers <span class=\"new\">NEW</span>","Easy: armies 0.75 of the base number, raiders as trained. Medium: armies 1.4 of it, each raider 1.25 times as strong. Hard: armies 1.9 of it, each raider 1.5 times as strong (section 14).","Keep, or tune?"]]}],"summary":"The five-star general NEW, Raid strength: the numbers NEW…"},{"id":"g-17-numbers-claude-code-proposed","cat":"guide","sec":"s17","secTitle":"17. Still Open","title":"Numbers Claude Code proposed","pic":"i:book","blocks":[{"t":"p","h":"These are in the current build. You can accept them or change them, and each is one line in the settings file."},{"t":"table","head":["Item","Current build value"],"rows":[["Tower ballista","400 gold, 150 wood (you agreed; it can change)"],["Tower trebuchet","800 gold, 300 wood, 100 stone"],["Market","Buy at 2.5 times, sell at 1.2 times. School level 2: 2 and 1.5. Level 3: 1.8 and 1.6."],["Wood huts","Stage 1: 4 huts of 2 people. Stage 2: 3 yards of 5 people."],["Winning","Every rival who is against you has lost his keep. The trading friend does not have to fall."],["Mill","Comes at stage 2 so the two-mills-before-stage-3 rule can apply."],["Macemen","Stage 3, with swordsmen."]]}],"summary":"These are in the current build. You can accept them or change them, and each is one line in the settings file."},{"id":"g-17-decided-since-version-2","cat":"guide","sec":"s17","secTitle":"17. Still Open","title":"Decided since version 2","pic":"i:book","blocks":[{"t":"table","head":["Item","Your decision, now in the game"],"rows":[["Moat fillers","Citizens, spearmen, swordsmen and flamethrowers. Never knights or anyone on a horse."],["Spikes","One strike kills, except knights, berserkers and mounted knights (two)."],["Peace time","10 minutes, 5 on Hard."],["Calling citizens","Back in the Town list, with happiness, wars won and generals balancing the cost."],["Fix button","The one over people: taken out. Remove &amp; rebuild stays in every building’s box."],["Double-click","Opens the person’s box."],["Troop controls","The diamond at the bottom left, with formations, patrol, guard and add."],["Boxes","One tap puts hints away; a double tap closes any box."],["Berserkers <span class=\"new\">NEW</span>","Every faction has them. Psychana’s power fits theirs: in small bands they move unseen."],["Raids <span class=\"new\">NEW</span>","Medium much stronger than Easy; Hard the strongest."],["Generals <span class=\"new\">NEW</span>","7 or more stars; a five-star general at 10."],["Wars won <span class=\"new\">NEW</span>","A raid where at least 6 in 10 raiders fell and your keep stands, or a rival defeated. Each counts for 10 minutes, up to 3 at once."],["Calling citizens: the numbers <span class=\"new\">NEW</span>","As in section 11."],["The diamond <span class=\"new\">NEW</span>","The arrows direct which way to go. Add puts more soldiers in the formation, and soldiers trained while it is on join it."],["A box beside the field <span class=\"new\">NEW</span>","A tap on a field or farm opens its box right beside it."],["Field and farm <span class=\"new\">NEW</span>","Two separate buildings. Field: up to 5, wheat (fastest), corn, grapes (slowest), you choose the people on each. Farm: up to 2, chickens, cows, pigs, ducks, seen in the pen; it gets better with a stable."],["Selling animals <span class=\"new\">NEW</span>","Farm animals always sell for the top price, far more than crops."],["Happy people, more food <span class=\"new\">NEW</span>","Food grows faster when people are happy."],["People in a field <span class=\"new\">NEW</span>","10 in a field, 5 in a farm: right."],["Alerts, compass, walls, voice <span class=\"new\">NEW</span>","All as described in What’s new; they work for every faction."],["Guards <span class=\"new\">NEW</span>","A knight’s strength whether or not knights can be trained: 2 for a field, 1 for a farm; free, coming with the building, as a tower comes with its knight."],["Turkeys, sheep, the vineyard <span class=\"new\">NEW</span>","Kept, with the field."],["Farm levels, well, lookout <span class=\"new\">NEW</span>","The numbers suit."],["Food first <span class=\"new\">NEW</span>","People pick food by themselves, first; food pickers are not called away; someone else takes the new work."],["Walking <span class=\"new\">NEW</span>","No glitching near the greenery or among people: they go round."],["“What is this?” <span class=\"new\">NEW</span>","Taken off the boxes."]]}],"summary":"Moat fillers, Spikes, Peace time…"},{"id":"g-17-still-being-finished","cat":"guide","sec":"s17","secTitle":"17. Still Open","title":"Still being finished","pic":"i:book","blocks":[{"t":"ul","items":["Higher-resolution art: the pictures of units and buildings here are the game’s own small pictures. Sheet-quality art for the newer soldiers is listed in design/MISSING-ART.md and design/IMAGE-PROMPTS.md.","All remaining stand-in art in the game is being finished.","The bug sweep goes on with every phase. Tell Claude Code anything that looks wrong, with where it happened.","Pictures of the game screens and boxes, and of the keep, were missing from version 2. They are in this version. <span class=\"new\">NEW</span>"]}],"summary":"Higher-resolution art: the pictures of units and buildings here are the game’s own small pictures.…"}]};
